    nexacro.Component = function (id, left, top, width, height, right, bottom, minwidth, maxwidth, minheight, maxheight, parent)
    {
        nexacro._EventSinkObject.call(this, id, parent);
       
        if (parent)
        {
            this._refform = this._findForm(parent);
            this._env = this._refform?._getEnvironment();
        }

        var horz = 0;
        var vert = 0;

        if (left != null) horz++;
        if (width != null) horz++;
        if (right != null) horz++;
        if (top != null) vert++;
        if (height != null) vert++;
        if (bottom != null) vert++;

        if (horz >= 2 && vert >= 2)
        {
            this._p_left = left;
            this._p_top = top;
            this._p_width = width;
            this._p_height = height;
            if (!this._isWidthUnset() && (left == undefined || width == undefined || right == undefined))
                this._p_right = right;
            if (!this._isHeightUnset() && (top == undefined || height == undefined || bottom == undefined))
                this._p_bottom = bottom;

            this._setMaxwidth(maxwidth);
            this._setMinwidth(minwidth);
            this._setMaxheight(maxheight);
            this._setMinheight(minheight);

            this._parseArrangeInfo(left, top, right, bottom, width, height);
            this._calcBasisSize();
            this._calcArrangePosition();
        }
        this._makeStatusMap();
    };

