    {
        return [this._adjust_width, this._adjust_height];
    };

    // 음수면 0으로 clamp
    _pComponent._clampToNonNegative = function (value)
    {
        return value < 0 ? 0 : value;
    };

    _pComponent._getSizeInfo = function ()
    {        
        var form = this._is_group ? this._group_panel : this._p_parent;
        var manager;
        if (form)
        {
            const env = form._getEnvironment();
            if (!env) return;
            manager = env._getLayoutManager();
            if (!manager) return;
        }

        var width = this._getComputedPropWidth();
        var height = this._getComputedPropHeight();
        var minwidth = this._getComputedPropMinWidth();
        var minheight = this._getComputedPropMinHeight();

        var parent_comp = this._getParentComponent();
        var parent_fittocontents = parent_comp ? parent_comp._p_fittocontents : "none";

        var fit_type = this._p_fittocontents;
        var fit_size;

        // 1. 컨텐츠 크기 가져오기 (필요한 경우)
        if (fit_type === "width" || fit_type === "height" || fit_type === "both")
        {
            fit_size = this._on_getFitSize();
        }

        // 2. fit 적용 (음수는 0으로 clamp)
        if (fit_type === "width" || fit_type === "both")
        {
            var fit_width = this._clampToNonNegative(fit_size[0]);

            // fittocontents 결과가 0이고, 원래 % width가 있으면 fallback
            if (fit_width <= 0 && width
                && typeof width === "string"
                && width.indexOf("%") > -1)
            {
                var containerComp = this._getParentComponent();
                if (containerComp)
                {
                    var ref = containerComp._basis_width || containerComp._adjust_width;
                    if (ref > 0)
                    {
                        width = this._convToPixel(width, ref);
                    }
                }
            }
            else
            {
                width = fit_width;
            }

            //minwidth = width;
        }

        if (fit_type === "height" || fit_type === "both")
        {
            var fit_height = this._clampToNonNegative(fit_size[1]);

            // fittocontents 결과가 0이고, 원래 % height가 있으면 fallback
            if (fit_height <= 0 && height
                && typeof height === "string"
                && height.indexOf("%") > -1)
            {
                var containerComp = this._getParentComponent();
                if (containerComp)
                {
                    var ref = containerComp._basis_height || containerComp._adjust_height;
                    if (ref > 0)
                    {
                        height = this._convToPixel(height, ref);
                    }
                }
            }
            else
            {
                height = fit_height;
            }
        }


        var layouttype = form._getLayoutType(manager);
        /*
        manager.getLayoutProperty(form, "type");
        */
        // 3. fit_type이 default(none)일 때만 position 기반 보정
        //    (width/height/both는 컨텐츠 기반이므로 별도 보정 불필요)

        if (layouttype != "table" && fit_type !== "width" && fit_type !== "height" && fit_type !== "both")
        {
            this._fit_width = this._getAdjustFitPositionWidth(width, parent_fittocontents);
            this._fit_height = this._getAdjustFitPositionHeight(height, parent_fittocontents);

            width = this._fit_width;
            height = this._fit_height;
        }
        return [width, height, minwidth, minheight];
    };

    _pComponent._on_getFitSize_style = function ()    
    {
        var total_w = 0;
        var total_h = 0;
        var border = this._getCurrentStyleBorder();
        if (border)
        {
            total_w += border._getBorderWidth();
            total_h += border._getBorderHeight();
        }

        var padding = this._getCurrentStylePadding();
        if (padding)
        {
            total_w += padding.left + padding.right;
            total_h += padding.top + padding.bottom;
        }
        return [total_w, total_h];
    };

    _pComponent._on_getFitSize_scroll = function ()    
    {
        var total_w = 0;
        var total_h = 0;
        var fittocontents = this._getFittocontents();
        if (fittocontents == "width")
        {
            var vscrollbar = this ? this._p_vscrollbar : null;
            if (vscrollbar && vscrollbar._p_visible)
            {
                total_w += vscrollbar._adjust_width;
            }
            var hspinbar = this ? this._p_hspinbar : null;
            if (hspinbar && hspinbar._p_visible)
            {
                total_w += hspinbar._getOffsetLead() + hspinbar._getOffsetTail();
            }
        }

        if (fittocontents == "height")
        {
            var hscrollbar = this ? this._p_hscrollbar : null;
            if (hscrollbar && hscrollbar._p_visible)// && hscrollbar._adjust_top > -1)
            {
                total_h += hscrollbar._adjust_height;
            }
            var vspinbar = this ? this._p_vspinbar : null;
            if (vspinbar && vspinbar._p_visible)
            {
                total_w += vspinbar._getOffsetLead() + vspinbar._getOffsetTail();
            }
        }
        return [total_w, total_h];
    };

