	{
		navtarget = navtarget ? navtarget : this._p_navtarget;
		navurl = navurl ? navurl : this._p_navurl;

		if (!navtarget || !navurl) return;

		const env = this._getEnvironment();
		const app = env?._getApplication();
		if (!app) return;

		navtargetproperties = navtargetproperties ? navtargetproperties : this._p_navtargetproperties;
		if (navtargetproperties && typeof navtargetproperties == "string")
		{
			try
			{
				navtargetproperties = JSON.parse(navtargetproperties);
			}
 			catch (error)
			{
				navtargetproperties = undefined;
			}
		}

		const navidobj = app._getNavidObject(navtarget);
		if (!navidobj) return;

		navidobj.on_click_navigate(navurl, navtargetproperties);

		if (env && !env._p_preventbrowserbackbutton)	
		{
			if (navidobj._p_navtype == "alwaysnew")
			{
				return;
			}
			let statedata = { navtarget: navtarget, navurl: navurl, navtargetproperties: navtargetproperties };
			var hash = 0, str = navtarget + navurl;
			for (var i = 0; i < str.length; i++)
			{
				var chr = str.charCodeAt(i);
				hash = ((hash << 5) - hash) + chr;
				hash |= 0; // Convert to 32bit integer
			}
			hash = hash.toString();
			nexacro.History._pushState_internal(hash, "", statedata);
		}
	};

