    //==============================================================================
    // nexacro.DSColumnInfo
    // Dataset ColumnInfo
    //==============================================================================

    nexacro.DSColumnInfo = function (id, type, ntype, size, prop, sumtext, datapath, idx, label, datautils)
    {
        this.id = id;

        this._p_name = id;
        this._p_type = type;  //string : on caller this id Nomalized typeName : toLowerCase()
        this._p_size = size;
        this._p_prop = prop;
        this._p_sumtext = sumtext;
        this._p_datapath = datapath;
        this._p_label = label;
        
        this.ntype = ntype;    //integer
        this._index = idx;
        this._datautils = datautils || nexacro.getEnvironment()._datautils || nexacro.DataUtilsSet["1.0"];

        this._on_apply_columntype();
    };

    var _pDSColumnInfo = nexacro._createPrototype(nexacro.Object, nexacro.DSColumnInfo);
    nexacro.DSColumnInfo.prototype = _pDSColumnInfo;
    _pDSColumnInfo._type_name = "DSColumnInfo";

    _pDSColumnInfo.set_name = nexacro._emptyFn;

    _pDSColumnInfo.set_size = function (v)
    {
        v = +v;
        if (isFinite(v) && this._p_size != v)
        {
            this._p_size = v | 0;
        }
    };

    _pDSColumnInfo.set_type = function (v)
    {
        if (this._p_type != v)
        {
            v = nexacro._toString(v);
            var check = v.toLowerCase();
            var datautils = this._datautils;
            if (datautils._typeenums.indexOf(check) == -1)
            {
                return;
            }

            this._p_type = v;
            this.ntype = datautils._typeint[check];

            this._on_apply_columntype();
        }
    };

    _pDSColumnInfo.set_prop = function (v)
    {
        v = nexacro._toString(v);
        if (this._p_prop != v)
        {
            this._p_prop = v;
        }
    };

    _pDSColumnInfo.set_sumtext = function (v)
    {
        v = nexacro._toString(v);
        if (this._p_sumtext != v)
        {
            this._p_sumtext = v;
        }
    };

    _pDSColumnInfo.set_datapath = function (v)
    {
        v = nexacro._toString(v);
        if (this._p_datapath != v)
        {
            this._p_datapath = v;
            this.on_apply_datapath()
        }
    };

    _pDSColumnInfo.set_label = function (v)
    {
        v = nexacro._toString(v);
        if (this._p_label != v)
        {
            this._p_label = v;
        }
    };

    _pDSColumnInfo.on_apply_datapath = function ()
    {
        this._value = undefined;
    };

    // for test code
    _pDSColumnInfo._setDataUtils = function (datautils)
    {
        if (datautils)
            this._datautils = datautils;
        this._on_apply_columntype();
    };

    _pDSColumnInfo._on_apply_columntype = function ()
    {
        var ntype = this.ntype;
        var datautils = this._datautils;
        switch (ntype)
        {
            case 1:
                // string
                this._toText = datautils.toTextFromString;
                this._fromText = datautils.toStringFromText;
                this._fromVal = datautils.toString;
                this._toXMLText = datautils.toXMLTextFromString;
                this._fromXMLText = datautils.toStringFromXMLText;
                break;
            case 2:
                // int
                this._toText = datautils.toTextFromInt;
                this._fromText = datautils.toIntFromText;
                this._fromVal = datautils.toInt;
                this._toXMLText = datautils.toTextFromInt;
                this._fromXMLText = datautils.toIntFromText;
                break;
            case 3:
                // float
                this._toText = datautils.toTextFromFloat;
                this._fromText = datautils.toFloatFromText;
                this._fromVal = datautils.toFloat;
                this._toXMLText = datautils.toTextFromFloat;
                this._fromXMLText = datautils.toFloatFromText;
                break;
            case 4:
                // bigdecimal
                this._toText = datautils.toTextFromDecimal;
                this._fromText = datautils.toDecimalFromText;
                this._fromVal = datautils.toDecimal;
                this._toXMLText = datautils.toTextFromDecimal;
                this._fromXMLText = datautils.toDecimalFromText;
                break;
            case 5:
                // date
                this._toText = datautils.toTextFromDate;
                this._fromText = datautils.toDateFromText;
                this._fromVal = datautils.toDate;
                this._toXMLText = datautils.toTextFromDate;
                this._fromXMLText = datautils.toDateFromText;
                break;
            case 6:
                // time
                this._toText = datautils.toTextFromTime;
                this._fromText = datautils.toTimeFromText;
                this._fromVal = datautils.toTime;
                this._toXMLText = datautils.toTextFromTime;
                this._fromXMLText = datautils.toTimeFromText;
                break;
            case 7:
                // datetime
                this._toText = datautils.toTextFromDateTime;
                this._fromText = datautils.toDateTimeFromText;
                this._fromVal = datautils.toDateTime;
                this._toXMLText = datautils.toTextFromDateTime;
                this._fromXMLText = datautils.toDateTimeFromText;
                break;
            case 8:
                // blob
                this._toText = datautils.toTextFromBlob;
                this._fromText = datautils.toBlobFromText;
                this._fromVal = datautils.toBlob;
                this._toXMLText = datautils.toTextFromBlob;
                this._fromXMLText = datautils.toBlobFromText;
                break;
            default:
                // variant
                this._toText = datautils.toTextFromVariant;
                this._fromText = datautils.toVariantFromText;
                this._fromVal = datautils.toVariant;
                this._toXMLText = datautils.toXMLTextFromVariant;
                this._fromXMLText = datautils.toVariantFromXMLText;
                break;
        }
    };

    _pDSColumnInfo._properties = [{ name: "name" }, { name: "size" }, { name: "type" }, { name: "prop" }, { name: "sumtext" }, { name: "datapath" }, { name: "label" }];
    nexacro._defineProperties(_pDSColumnInfo, _pDSColumnInfo._properties);

    _pDSColumnInfo = null;

    nexacro.DSColumnInfoList = function ()
    {
        nexacro.Collection.apply(this);
    };
    var _pDSColumnInfoList = nexacro._createPrototype(nexacro.Collection, nexacro.DSColumnInfoList);
    nexacro.DSColumnInfoList.prototype = _pDSColumnInfoList;
    _pDSColumnInfoList._type_name = "DSColumnInfoList";

    _pDSColumnInfoList._updateID = function (idx, newID)
    {
        var colinfo = this[idx];
        if (colinfo && colinfo.id != newID)
        {
            colinfo.set_id(newID);
            return this.update_id(idx, newID);
        }
        return false;
    };

    _pDSColumnInfoList.deleteItem = function (id)
    {
        return this.delete_item(id);
    };
    _pDSColumnInfoList = null;

