    //===============================================================
    // nexacro._EditMaskTypeNumber : 
    // description : object for MaskEdit's type property
    //===============================================================
    nexacro._EditMaskTypeNumber = function ()
    {
        nexacro._EditMaskType.call(this);

        this.mask = "";
        this.limittype = "none";
        this.maskchar = "";
        this.fillchar = "0";

        this._input_mode = "number";

        this._decimal_point = ".";
        this._thousands_sep = ",";
        this._mask_decimal_point = ".";
        this._mask_thousands_sep = ",";

        this._init();
    };
    var _pMaskTypeNumber = nexacro._createPrototype(nexacro._EditMaskType, nexacro._EditMaskTypeNumber);
    nexacro._EditMaskTypeNumber.prototype = _pMaskTypeNumber;
    _pMaskTypeNumber._type_name = "MaskTypeNumber";

    nexacro._EditMaskTypeNumber._put_thousand_seperator = function (text, grouping)
    {
        if (!text || !grouping) return text;

        var group = grouping[0];
        if (!group || group < 1) return text;

        var reg;
        if (grouping.length > 1)
        {
            grouping.shift();

            // /\B(?=(\d{3})+(?!\d))/g
            reg = new RegExp("(\\d+)(\\d{" + group + "})($|\\.\\d+)");
            if (reg.test(text))
            {
                return text.replace(reg, function (str, p1, p2, p3) { return nexacro._EditMaskTypeNumber._put_thousand_seperator(p1, grouping) + ',' + p2 + p3; });
            }
        }
        else
        {
            reg = new RegExp("\\B(?=(\\d{" + group + "})+(?!\\d))", "g");
            if (reg.test(text))
            {
                return text.replace(reg, ',');
            }
        }
        return text;
    };

    _pMaskTypeNumber._init = function ()
    {
        this.locale = "";

        this._grouping = [];
        this._sign_type = 3;  // -:0, +:1, !:2, undefined:3
        this._sign_sep_by_space = 0;

        this._init_digits();

        this._masked_empty_text = "";

        this._is_max_intpart = false;
        this._is_max_decpart = false;

        this._use_grouping = false;
    };

    _pMaskTypeNumber._init_digits = function ()
    {
        this._is_integer_mask = false;

        this._is_intpart_zero = true;
        this._is_decpart_zero = true;
        this._is_intpart_nine = false;

        this._int_digits_min = 0;
        this._int_digits_max = -1;
        this._dec_digits_min = 0;
        this._dec_digits_max = -1;
        this._dec_min_sharp = -1;
        this._dec_max_sharp = -1;
    };

    _pMaskTypeNumber.setMask = function (mask)
    {
        if (this.mask != mask)
        {
            this.mask = mask;
            this._parseMask(mask);
        }
    };

    _pMaskTypeNumber.setUseGrouping = function (bgroup)
    {
        if (this._use_grouping != bgroup)
        {
            this._use_grouping = bgroup;
        }
    };

    _pMaskTypeNumber._parseMask = function (mask)
    {
        this._init_digits();
        if (!mask || mask === ".")
        {
            return;
        }

        //var reg_valid = /^[\+\-]?\s*[#09]{1,}[#09,]*(?:$|\.[#09]*)/;
        var reg_valid = /(^[\+\-\!]?\s*[#09,]*(?:$|\.[#09]*)|^\.[#09]*$)/;
        if (!reg_valid.test(mask)) return;

        // parse sign part
        var sign_char = mask[0];
        switch (sign_char)
        {
            case '-': this._sign_type = 0; break;
            case '+': this._sign_type = 1; break;
            case '!': this._sign_type = 2; break;
            default: { this._sign_type = 3; sign_char = ''; } break;
        }

        var len = mask.length;
        var sign_sep_by_space = 0;
        var empty_value, i;

        if (this._sign_type != 3)
        {
            for (i = 1; i < len; i++)
            {
                var c = mask[i];
                if (c == '#' || c == '9' || c == '0') break;
                if (c != ' ') return;

                sign_sep_by_space++;
            }
        }
        this._sign_sep_by_space = sign_sep_by_space;

        // split each part
        var point_char = this._mask_decimal_point;
        var point_idx = mask.indexOf(point_char);

        // check integer type
        this._is_integer_mask = (point_idx < 0);

        var int_part = "", dec_part = "";
        if (this._is_integer_mask)
        {
            int_part = mask.substring(sign_char.length + sign_sep_by_space);
        }
        else
        {
            int_part = mask.substring((sign_char.length + sign_sep_by_space), point_idx);
            dec_part = mask.substring(point_idx + 1);

            if (dec_part)
            {
                var idx_sharp, is_fixed_min_sharp;
                idx_sharp = dec_part.indexOf("#");
                if (idx_sharp > -1)
                {
                    is_fixed_min_sharp = false;
                    this._dec_max_sharp = idx_sharp;
                    for (i = dec_part.length - 1; i >= idx_sharp; i--)
                    {
                        if (dec_part[i] == "#")
                        {
                            if (this._dec_min_sharp == -1)
                                this._dec_min_sharp = i;
                            if (this._dec_max_sharp < i)
                            {
                                this._dec_max_sharp = i;
                            }
                            if (this._dec_min_sharp > i && is_fixed_min_sharp == false)
                                this._dec_min_sharp = i;
                        }
                        else if (this._dec_min_sharp != -1)
                            is_fixed_min_sharp = true;
                    }
                }
            }
        }

        // parse thousands grouping
        var thousands_sep = this._mask_thousands_sep;
        if (mask.indexOf(thousands_sep) > -1)
        {
            this.setUseGrouping(true);
        }
        else
        {
            this.setUseGrouping(false);
        }

        int_part = int_part.split(thousands_sep).join('');

        // integer max digits
        var int_digits = int_part.length;
        this._int_digits_max = int_digits;

        // integer min digits
        var idx = int_part.indexOf('0');
        if (idx > -1) this._int_digits_min = int_digits - idx;

        // integer view zero
        var last_int_mask = int_digits ? int_part[int_digits - 1] : "";
        if (idx == -1)
        {
            if (last_int_mask == "#")
            {
                this._is_intpart_zero = false;
            }
            else if (last_int_mask == "9")
            {
                this._is_intpart_zero = false;
                this._is_intpart_nine = true;
            }
        }

        if (this._int_digits_min > 0)
        {
            empty_value = "";
            for (i = 0; i < this._int_digits_min; i++)
                empty_value += '0';

            var grouping = this._grouping.slice(0);
            if (grouping.length > 0)
            {
                this._masked_empty_text = nexacro._EditMaskTypeNumber._put_thousand_seperator(empty_value, grouping);
            }
            else
            {
                this._masked_empty_text = empty_value;
            }
        }
        else
        {
            this._masked_empty_text = "";
        }

        if (this._is_integer_mask)
            return;

        dec_part = dec_part.replace(/[.]/g, '');

        // decimal max digit
        var dec_digits = dec_part.length;
        this._dec_digits_max = dec_digits;

        // decimal max digit
        idx = dec_part.lastIndexOf('0');
        if (idx > -1) this._dec_digits_min = idx + 1;

        // decimal view zero
        var last_dec_mask = dec_digits ? dec_part[0] : "";
        if (idx == -1 && last_dec_mask == "#") this._is_decpart_zero = false;

        if (this._dec_digits_min > 0)
        {
            empty_value = this._decimal_point;
            for (i = 0; i < this._dec_digits_min; i++)
                empty_value += '0';

            this._masked_empty_text += empty_value;
        }
    };

    _pMaskTypeNumber.setLocale = function (v)
    {
        if (v != this.locale)
        {
            this.locale = v;

            var info = nexacro.Locale.getLocaleInfo(v);
            var first_group = info.grouping[0];
            this._thousands_sep = info.thousands_sep ? info.thousands_sep : this._mask_thousands_sep;

            if (first_group == 0 || first_group == -1)
            {
                this._grouping = [3];
            }
            else
            {
                this._grouping = info.grouping;
            }

            if (this._decimal_point != info.decimal_point)
            {
                this._decimal_point = info.decimal_point;
                if (this._dec_digits_min > 0)
                {
                    this._masked_empty_text = "0";
                    var empty_value = this._decimal_point;

                    for (var i = 0; i < this._dec_digits_min; i++)
                    {
                        empty_value += "0";
                    }

                    this._masked_empty_text += empty_value;
                }
            }
        }
    };

    _pMaskTypeNumber.setLimitType = function (v)
    {
        if (this.limittype != v)
        {
            this.limittype = v;

            this._check_int_max = (v == "both" || v == "integer");
            this._check_dec_max = (v == "both" || v == "decimal");
        }
    };

    _pMaskTypeNumber.applyMask = function (value)
    {
        var bfillzero = !this._is_editing;
        this._is_max_intpart = false;
        this._is_max_decpart = false;

        var text = nexacro._toString(value);
        if (!text) return (bfillzero ? this._masked_empty_text : "");

        text = text.replace(/^\s\s*/, '').replace(/[,]/g, '');

        var pos = 0;
        var len = text.length;
        var postfixtext = this.postfixtext;

        // unsetted mask
        var bmask = (this._int_digits_max == -1 && this._dec_digits_max == -1) ? false : true;

        // check sign symbol
        var sign_char = text[pos++];
        if (sign_char != '+' && sign_char != '-')
        {
            pos -= 1;
            sign_char = '';
        }
        for (; pos < len; pos++)
        {
            var c = text[pos];
            if ((c >= '0' && c <= '9') || c == ',' || c == '.') break;
            if (c != ' ') return (bfillzero ? this._masked_empty_text : "");
        }

        // split each part
        var point_char = this._mask_decimal_point;
        var point_idx = text.indexOf(point_char);

        var int_part = "", dec_part = "";
        if (point_idx < 0)
        {
            int_part = text.substring(pos);
            int_part = !bmask ? int_part.padLeft(1, "0") : int_part;
        }
        else
        {
            int_part = text.substring(pos, point_idx);
            dec_part = text.substring(point_idx + 1);

            int_part = !bmask ? int_part.padLeft(1, "0") : int_part;
            dec_part = !bmask ? dec_part.padLeft(1, "0") : dec_part;
        }
        if (!this._is_intpart_zero)
        {
            if (!this._is_intpart_nine || dec_part)
                int_part = (int_part.length && +int_part === 0) ? "" : int_part;
        }
        if (!this._is_decpart_zero) dec_part = (dec_part.length && +dec_part === 0) ? "" : dec_part;

        if ((int_part.length > 0 && !(/^(?:[0-9]*)$/.test(int_part)))
            || (dec_part.length > 0 && !(/^(?:[0-9]*)$/.test(dec_part))))
        {
            return (bfillzero ? this._masked_empty_text : "");
        }

        // check thousands grouping
        var i, idx, prev_idx = int_part.length - 1;
        var thousands_sep = this._thousands_sep;
        var grouping = [];
        if (this._use_grouping)
        {
            grouping = this._grouping.slice(0);
        }

        // incorrect thousand separator
        for (i = 0; ; i++)
        {
            idx = int_part.lastIndexOf(thousands_sep, prev_idx);
            if (idx < 0) break;

            var group = grouping[(i < grouping.length ? i : grouping.length - 1)];
            if (!group || (prev_idx - idx) != group)
                return (bfillzero ? this._masked_empty_text : "");

            prev_idx = idx - 1;
        }

        //----------------------------------------------------------------
        var masked_text = sign_char;
        if (sign_char != '')
        {
            for (i = 0; i < this._sign_sep_by_space; i++)
                masked_text += ' ';
        }

        int_part = int_part.split(thousands_sep).join('');

        var int_digits = int_part.length;
        var int_max = this._int_digits_max;
        if (int_digits >= int_max)
        {
            this._is_max_intpart = true;
        }

        // check integer min/max : whenever value set on script or bind, do not check integer max.
        var int_min = this._int_digits_min;
        var fillcnt;

        if (bfillzero && int_min > 0)
        {
            fillcnt = int_min - int_digits;
            for (i = 0; i < fillcnt; i++)
            {
                int_part = '0' + int_part;
            }
        }

        // put thousand separator
        int_part = nexacro._EditMaskTypeNumber._put_thousand_seperator(int_part, grouping);
        int_part = int_part.replace(/,/g, thousands_sep);

        masked_text += int_part;

        if (this._is_integer_mask)
        {
            if (postfixtext && !this._is_editing)
                masked_text += postfixtext;

            return masked_text;
        }

        // check decimal min/max
        var dec_digits = dec_part.length;
        var dec_min = this._dec_digits_min;
        var dec_max = this._dec_digits_max;
        if (dec_digits >= dec_max)
        {
            this._is_max_decpart = true;
        }

        if (bfillzero && dec_min > 0)
        {
            fillcnt = dec_min - dec_digits;
            for (i = 0; i < fillcnt; i++)
            {
                dec_part += '0';
            }
        }

        if (this._check_dec_max && dec_max > -1 && dec_part.length > dec_max)
        {
            dec_part = dec_part.substring(0, dec_max);
        }

        var dec_max_sharp = this._dec_max_sharp;
        if (dec_max_sharp >= dec_max - 1)
        {
            var dec_min_zero = -1;
            var dec_min_sharp = this._dec_min_sharp;
            for (i = dec_max_sharp; i >= dec_min_sharp; i--)
            {
                if (dec_part[i] == 0)
                    dec_min_zero = i;// - 1;
                else if (dec_max_sharp == i)
                    break;
            }
            if (dec_min_zero > -1)
                dec_part = dec_part.slice(0, dec_min_zero);
        }

        if (dec_part != "")
        {
            masked_text += this._decimal_point;
            masked_text += dec_part;
        }
        else if (this._is_editing && point_idx > -1)
        {
            masked_text += this._decimal_point;
        }

        if (postfixtext && !this._is_editing)
            masked_text += postfixtext;

        return masked_text;
    };

    _pMaskTypeNumber.arrangeMask = function (input_text, begin, end)
    {
        this._is_max_intpart = false;
        this._is_max_decpart = false;

        var text = nexacro._toString(input_text);
        if (!text) return { "text": "", "pos": end };

        var result_buf = [];
        var decimal_point = this._decimal_point;
        var thousands_sep = this._thousands_sep;

        text = text.replace(/^\s\s*/, '');
        var input_ch = input_text.substring(begin, end);
        if (input_ch == '+' || input_ch == '-') text = text.substring(0, begin) + text.substring(end);

        var textlen = text.length;
        var pos = 0, end_rpos = input_text.length - end;
        var ch = text[pos];
        var newpos = 0;

        if (input_ch == '+' && (this._sign_type == 1 || this._sign_type == 3))
        {
            if (ch == '+')
            {
                result_buf.push("");
                pos++;
            }
            else
            {
                result_buf.push(input_ch);
                if (ch == '-') pos++;
            }
        }
        else if (input_ch == '-' && (this._sign_type == 0 || this._sign_type == 3))
        {
            if (ch == '-')
            {
                result_buf.push("");
                pos++;
            }
            else
            {
                result_buf.push(input_ch);
                if (ch == '+') pos++;
            }
        }

        var is_sign_pushed = false;
        for (; pos < textlen; pos)
        {
            ch = text[pos];
            if ((ch >= '0' && ch <= '9') || ch == ',' || ch == '.') break;
            if (ch != ' ' && ch != '-' && ch != '+') return null;

            if (ch == '-' || ch == '+')
            {
                if (is_sign_pushed
                    || (ch == '-' && !(this._sign_type == 0 || this._sign_type == 3))
                    || (ch == '+' && !(this._sign_type == 1 || this._sign_type == 3)))
                {
                    pos++;
                    continue;
                }
                is_sign_pushed = true;
            }

            result_buf.push(ch);
            pos++;
        }

        // integer part
        var int_buf = [], buf_len = 0;
        var bTrimZero = true, intpart_last_char;
        var int_begin_pos = pos, splice_begin = -1, changed_cnt = 0;
        while (pos < textlen)
        {
            ch = text[pos];
            if (!ch || ch == decimal_point) break;

            pos++;
            if (ch == thousands_sep)
                continue;

            if (!(ch >= '0' && ch <= '9'))
                continue;

            intpart_last_char = ch;
            if (bTrimZero)
            {
                if (ch == '0')
                    continue;

                bTrimZero = false;
            }

            buf_len = int_buf.push(ch);
            if (pos <= end)
            {
                if (pos > begin)
                    changed_cnt++;

                splice_begin = buf_len;
            }
        }

        // this should check in arrangeMask function only.
        var int_len = int_buf.length;
        var int_max = this._int_digits_max;
        var chk_int_max = (this._check_int_max && int_max > -1);
        var over_cnt;

        if (chk_int_max && begin < pos && end > int_begin_pos)
        {
            over_cnt = int_len - int_max;
            if (over_cnt > 0 && changed_cnt > 0) // for backspace, check changed_cnt
            {
                if (over_cnt > changed_cnt)
                    int_buf.splice(splice_begin - changed_cnt, changed_cnt);
                else
                    int_buf.splice(splice_begin - over_cnt, over_cnt);

                int_len = int_buf.length;
            }
        }

        if (int_buf.length == 0 && intpart_last_char == '0')
        {
            int_len = int_buf.push('0');
        }

        if (int_len >= int_max)
        {
            this._is_max_intpart = true;
        }

        if (int_buf.length > 0)
        {
            var grouping = [];
            if (this._use_grouping)
            {
                grouping = this._grouping.slice(0);
            }
            var int_part = nexacro._EditMaskTypeNumber._put_thousand_seperator(int_buf.join(''), grouping);
            result_buf.push(int_part.replace(/,/g, thousands_sep));
        }

        // decimal point
        if (pos < textlen)
        {
            if (this._is_integer_mask)
                return null;

            // 연산자 우선 순위가 크롬에서 오류나서 변경
            ch = text[pos];
            if (ch != decimal_point)
            {
                input_text = result_buf.join('');
                newpos = (input_text.length < end_rpos ? end : input_text.length - end_rpos);

                // String 방식과 마찬가지로 통과된 결과에 대해서만 리턴
                return { "text": input_text, "pos": newpos };
            }

            pos++;
            result_buf.push(ch);
        }

        // decimal part
        var dec_buf = [];
        var dec_begin_pos = pos;
        splice_begin = -1;
        changed_cnt = 0;
        while (pos < textlen)
        {
            ch = text[pos];
            if (!(ch >= '0' && ch <= '9'))
            {
                if (dec_buf.length > 0)
                {
                    result_buf.push(dec_buf.join(''));
                }

                input_text = result_buf.join('');
                newpos = (input_text.length < end_rpos ? end : input_text.length - end_rpos);

                // String 방식과 마찬가지로 통과된 결과에 대해서만 리턴
                return { "text": input_text, "pos": newpos };
            }

            pos++;
            buf_len = dec_buf.push(ch);
            if (pos <= end)
            {
                if (pos > begin)
                    changed_cnt++;

                splice_begin = buf_len;
            }
        }

        var dec_max = this._dec_digits_max;
        var chk_dec_max = (this._check_dec_max && dec_max > -1);
        var dec_len = dec_buf.length;

        if (chk_dec_max && end > begin && end > dec_begin_pos)
        {
            over_cnt = dec_len - dec_max;
            if (over_cnt > 0 && changed_cnt > 0) // for backspace, check changed_cnt
            {
                if (over_cnt > changed_cnt)
                    dec_buf.splice(splice_begin - changed_cnt, changed_cnt);
                else
                    dec_buf.splice(splice_begin - over_cnt, over_cnt);
            }
            dec_len = dec_buf.length;
        }

        if (dec_len >= dec_max)
        {
            this._is_max_decpart = true;
        }

        if (dec_buf.length > 0)
        {
            result_buf.push(dec_buf.join(''));
        }

        input_text = result_buf.join('');
        newpos = (input_text.length < end_rpos ? end : input_text.length - end_rpos);

        return { "text": input_text, "pos": newpos };
    };

    _pMaskTypeNumber.removeMask = function (masked_text)
    {
        var text = nexacro._toString(masked_text);
        if (!text) return "";

        text = text.replace(/^\s\s*/, '');
        var textlen = text.length;

        var result_buf = [];
        var decimal_point = this._decimal_point;
        var thousands_sep = this._thousands_sep;

        // check sign symbol
        var pos = 0;
        var ch = text[pos];
        if (ch == '+' || ch == '-')
        {
            if (ch == '-')
                result_buf.push(ch);
            pos++;
        }

        for (; pos < textlen; pos++)
        {
            ch = text[pos];
            if ((ch >= '0' && ch <= '9') || ch == ',' || ch == '.') break;
            if (ch != ' ') return result_buf.join('');
        }

        if (pos == textlen)
            return "";

        // integer part
        var bTrimZero = true;
        while (pos < textlen)
        {
            ch = text[pos];
            if (!ch || ch == decimal_point) break;

            pos++;
            if (ch == thousands_sep) continue;
            if (!(ch >= '0' && ch <= '9'))
            {
                return result_buf.join('');
            }

            if (bTrimZero)
            {
                if (ch == '0')
                    continue;
                bTrimZero = false;
            }

            result_buf.push(ch);
        }

        var int_is_zero = false;
        if (bTrimZero)
        {
            result_buf.push('0');
            int_is_zero = true;
        }

        if (this._is_integer_mask)
        {
            return result_buf.join('');
        }

        // decimal point
        if (pos < textlen)
        {
            ch = text[pos++];
            if (ch != decimal_point)
            {
                return result_buf.join('');
            }
        }

        // decimal part
        var dec_buf = [];
        var dec_max = this._dec_digits_max;
        var chk_dec_max = (this._check_dec_max && dec_max > -1);

        var dec_digits = textlen - pos;
        if (chk_dec_max && dec_digits > dec_max)
            dec_digits = dec_max;

        if (dec_digits > 0)
        {
            ch = text[pos];
            if (!(ch >= '0' && ch <= '9'))
                return result_buf.join('');

            dec_buf.push(ch);
        }

        bTrimZero = true;
        for (var i = dec_digits - 1; i > 0; i--)
        {
            ch = text[pos + i];
            if (!(ch >= '0' && ch <= '9'))
                return result_buf.join('');

            if (bTrimZero)
            {
                if (ch == '0')
                    continue;
                bTrimZero = false;
            }

            dec_buf[i] = ch;
        }
        if (dec_buf.length > 0)
        {
            var dec = dec_buf.join('');
            if (!int_is_zero || dec != '0')
            {
                result_buf.push(this._mask_decimal_point);
                result_buf.push(dec);
            }
        }

        return result_buf.join('');
    };

    _pMaskTypeNumber.isDeletableChar = function (ch/*, pos*/)
    {
        if (ch == this._thousands_sep)
            return false;
        return true;
    };

    _pMaskTypeNumber.isFilterChar = function (ch/*, pos*/)
    {
        if (/[,\.\+\-0-9\s]/.test(ch))
            return false;
        return true;
    };

    _pMaskTypeNumber.isFilled = function ()
    {
        var isfill = false;

        if (this._is_integer_mask)
        {
            isfill = this._is_max_intpart;
        }
        else
        {
            isfill = this._is_max_decpart;
        }

        return isfill;
    };

    //delete _pMaskTypeNumber;
    _pMaskTypeNumber = null;

    //===============================================================
    // nexacro._EditMaskTypeString : 
    // description : object for MaskEdit's type property
    //===============================================================
    nexacro._EditMaskTypeString = function ()
    {
        nexacro._EditMaskType.call(this);

        this.mask = "";
        this.maskchar = "_";
        this.fillchar = " ";

        this._input_mode = "text";

        this._char_buf = []; // inputed char (for password type)
        this._is_filled = false;
        this._is_mismatch = false;

        this._init();
    };
    var _pMaskTypeString = nexacro._createPrototype(nexacro._EditMaskType, nexacro._EditMaskTypeString);
    nexacro._EditMaskTypeString.prototype = _pMaskTypeString;
    _pMaskTypeString._type_name = "MaskTypeString";

    _pMaskTypeString._init = function ()
    {
        this._masked_empty_text = "";
        this._mask_buf = [];
        this._value_buf = [];

        this._input_mode = "text";
        this._is_filled = false;
        this._is_mismatch = false;
    };

    _pMaskTypeString.setMask = function (mask)
    {
        if (this.mask != mask)
        {
            this.mask = mask;
            this._parseMask(mask);
        }
    };

    _pMaskTypeString._parseMask = function (mask)
    {
        this._init();

        if (!mask) return;

        var ch, pos = 0;
        var mask_buf = this._mask_buf;
        var value_buf = this._value_buf;
        var empty_buf = [];
        var maskchar = this.maskchar;
        var bNumberMaskOnly;

        var bQuote = false;
        var nBrace = 0;

        while ((ch = mask[pos++]))
        {
            switch (ch)
            {
                case '@':
                    {
                        mask_buf.push(/[\u0020-\u00ff]/);
                        value_buf.push(nBrace > 0 ? '*' : '$1');
                        empty_buf.push(maskchar);
                        bNumberMaskOnly = false;
                    }
                    break;
                case '#':
                    {
                        mask_buf.push(/\d/);
                        value_buf.push(nBrace > 0 ? '*' : '$1');
                        empty_buf.push(maskchar);
                        if (bNumberMaskOnly == undefined) bNumberMaskOnly = true;
                    }
                    break;
                case '*':
                    {
                        mask_buf.push(/[a-zA-Z]/);
                        value_buf.push(nBrace > 0 ? '*' : '$1');
                        empty_buf.push(maskchar);
                        bNumberMaskOnly = false;
                    }
                    break;
                case '9':
                    {
                        mask_buf.push(/[a-zA-Z0-9]/);
                        value_buf.push(nBrace > 0 ? '*' : '$1');
                        empty_buf.push(maskchar);
                        bNumberMaskOnly = false;
                    }
                    break;
                case 'A':
                    {
                        mask_buf.push(/[a-zA-Z]/);
                        value_buf.push(nBrace > 0 ? '*.toUpperCase()' : '$1.toUpperCase()');
                        empty_buf.push(maskchar);
                        bNumberMaskOnly = false;
                    }
                    break;
                case 'a':
                    {
                        mask_buf.push(/[a-zA-Z]/);
                        value_buf.push(nBrace > 0 ? '*.toLowerCase()' : '$1.toLowerCase()');
                        empty_buf.push(maskchar);
                        bNumberMaskOnly = false;
                    }
                    break;
                case 'Z':
                    {
                        mask_buf.push(/[a-zA-Z0-9]/);
                        value_buf.push(nBrace > 0 ? '*.toUpperCase()' : '$1.toUpperCase()');
                        empty_buf.push(maskchar);
                        bNumberMaskOnly = false;
                    }
                    break;
                case 'z':
                    {
                        mask_buf.push(/[a-zA-Z0-9]/);
                        value_buf.push(nBrace > 0 ? '*.toLowerCase()' : '$1.toLowerCase()');
                        empty_buf.push(maskchar);
                        bNumberMaskOnly = false;
                    }
                    break;
                case '\'':
                    {
                        bQuote = true;
                        while ((ch = mask[pos++]))
                        {
                            if (ch == '\'')
                            {
                                bQuote = false;
                                break;
                            }
                            if (ch == '\\')
                                ch = mask[pos++];

                            if (ch)
                            {
                                mask_buf.push(ch);
                                value_buf.push('');
                                empty_buf.push(ch);
                            }
                        }

                        if (bQuote) return; // invalid format
                    }
                    break;
                case '{':
                    {
                        nBrace++;
                    }
                    break;
                case '}':
                    {
                        nBrace--;
                    }
                    break;
                case '\\':
                    {
                        ch = mask[pos++];
                        if (ch)
                        {
                            mask_buf.push(ch);
                            value_buf.push('');
                            empty_buf.push(ch);
                        }
                    }
                    break;
                default:
                    {
                        mask_buf.push(ch);
                        value_buf.push('');
                        empty_buf.push(ch);
                    }
                    break;
            }
        }

        if (bNumberMaskOnly)
        {
            this._input_mode = "number";
        }

        this._masked_empty_text = empty_buf.join('');
    };

    _pMaskTypeString.setMaskChar = function (ch)
    {
        if (this.maskchar != ch)
        {
            this.maskchar = ch;
            this._parseMask(this.mask);
        }
    };

    _pMaskTypeString.applyMask = function (value)
    {
        this._is_filled = false;
        this._is_mismatch = false;

        var text = nexacro._toString(value);
        if (!text) return this._masked_empty_text;

        var mask_buf = this._mask_buf;
        var value_buf = this._value_buf;
        var char_buf = this._char_buf;
        var result_buf = [];
        var masked_text = "";

        var ch, mask, val;
        var bufpos = 0, txtpos = 0;
        //var mask_len = mask_buf.length;

        var maskchar = this.maskchar;
        var fillchar = this.fillchar;
        var postfixtext = this.postfixtext;

        var is_filled = true;
        while ((mask = mask_buf[bufpos]))
        {
            val = value_buf[bufpos];
            if (val == "")
            {
                result_buf.push(mask);
                if ((this.mask.length == text.length) && (mask == text[txtpos]))
                {
                    txtpos++;
                }
            }
            else
            {
                while (true) 
                {
                    ch = text[txtpos++];

                    if (!ch || mask.test(ch) || ch === fillchar || ch === "\u200e") 
                    {
                        break;
                    }

                    this._is_mismatch = true;
                }

                if (!ch || (fillchar != "" && ch == fillchar) || !mask.test(ch))
                {
                    char_buf[bufpos] = '';
                    result_buf.push(maskchar);
                    is_filled = false;
                }
                else if (val == "*")
                {
                    char_buf[bufpos] = ch;
                    result_buf.push(val);
                }
                else if (val == "$1")
                {
                    char_buf[bufpos] = ch;
                    result_buf.push(ch);
                }
                else if (val == "*.toUpperCase()")
                {
                    char_buf[bufpos] = ch.toUpperCase();
                    result_buf.push('*');
                }
                else if (val == "*.toLowerCase()")
                {
                    char_buf[bufpos] = ch.toLowerCase();
                    result_buf.push('*');
                }
                else if (val == "$1.toUpperCase()")
                {
                    char_buf[bufpos] = ch.toUpperCase();
                    result_buf.push(ch);
                }
                else if (val == "$1.toLowerCase()")
                {
                    char_buf[bufpos] = ch.toLowerCase();
                    result_buf.push(ch);
                }
                else
                {
                    char_buf[bufpos] = ch;
                    if (val[0] === '*')
                    {
                        result_buf.push('*');
                    }
                    else 
                    {
                        result_buf.push(ch);
                    }
                }
            }
            bufpos++;
        }
        this._is_filled = is_filled;

        masked_text = result_buf.join('');

        var resultval = "";
        var strval = nexacro._toString(value);
        if (strval)
        {
            resultval = strval.replace(/(\s*)/g, "");    // 공백제거..
        }

        if (postfixtext && !this._is_editing && resultval)
            masked_text += postfixtext;

        return masked_text;
    };

    _pMaskTypeString.arrangeMask = function (input_text, begin, end)
    {
        var mask_buf = this._mask_buf;
        var value_buf = this._value_buf;
        var char_buf = this._char_buf;

        var mask_len = mask_buf.length;
        if (mask_len == 0)
            return { "text": input_text, "pos": end };

        var text = nexacro._toString(input_text);
        var over_cnt = text.length - mask_len;
        var target_text = text.substr(0, over_cnt);
        var over_text = text.substr(over_cnt);
        if (target_text == over_text)
        {
            return { "text": target_text, "pos": end };
        }

        var text_buf = text.split('');
        var mask, ch;
        var maskchar = this.maskchar;
        var val, i, fillchar = this.fillchar;

        for (i = begin; i < end; i++)
        {
            val = value_buf[i];
            if (val == null) break;

            if (val == "")
            {
                if (text_buf[i] != mask_buf[i])
                {
                    end++;
                    over_cnt++;
                    text_buf.splice(i, 0, mask_buf[i]);
                }
            }
            //else if (text_buf[i] == "-")
            //{
            //	end--;
            //	over_cnt--;
            //	i--;
            //	text_buf.splice(i, 1);
            //}
            else
            {
                mask = mask_buf[i];
                ch = text_buf[i];

                if (!ch || (fillchar != "" && ch == fillchar) || !mask.test(ch))
                {
                    char_buf[i] = '';
                    text_buf[i] = maskchar;
                }
                else if (val == "*")
                {
                    char_buf[i] = ch;
                    text_buf[i] = '*';
                }
                else if (val == "$1")
                {
                    char_buf[i] = ch;
                    text_buf[i] = ch;
                }
                else if (val == "*.toUpperCase()")
                {
                    char_buf[i] = ch.toUpperCase();
                    text_buf[i] = '*';
                }
                else if (val == "*.toLowerCase()")
                {
                    char_buf[i] = ch.toLowerCase();
                    text_buf[i] = '*';
                }
                else if (val == "$1.toUpperCase()")
                {
                    char_buf[i] = ch.toUpperCase();
                    text_buf[i] = ch;
                }
                else if (val == "$1.toLowerCase()")
                {
                    char_buf[i] = ch.toLowerCase();
                    text_buf[i] = ch;
                }
                else
                {
                    char_buf[i] = ch;
                    if (val[0] === '*')
                    {
                        text_buf[i].push('*');
                    }
                    else 
                    {
                        text_buf[i].push(ch);
                    }
                }
            }
        }

        if (end < mask_len)
        {
            if (over_cnt > 0)
            {
                text_buf.splice(end, over_cnt);
            }
            else if (over_cnt < 0)
            {
                over_cnt = -(over_cnt);
                for (i = 0; i < over_cnt; i++)
                {
                    var pos = end + i;
                    val = value_buf[pos];
                    if (val == "")
                    {
                        text_buf.splice(pos, 0, mask_buf[pos]);
                    }
                    else
                    {
                        text_buf.splice(pos, 0, maskchar);
                        char_buf[pos] = "";
                    }
                }
            }
        }
        else
        {
            end = mask_len;
            text_buf.splice(end, (text_buf.length - end));
        }

        return { "text": text_buf.join(''), "pos": end };
    };

    _pMaskTypeString.removeMask = function (masked_text)
    {
        var mask_buf = this._mask_buf;
        var value_buf = this._value_buf;
        var char_buf = this._char_buf;

        this._is_filled = false;
        var mask_len = mask_buf.length;
        if (mask_len == 0)
            return masked_text;

        var maskchar = this.maskchar;
        var fillchar = this.fillchar;

        var text = nexacro._toString(masked_text);

        var ch, val, bufpos = 0;
        var result_buf = [];
        var is_filled = true;
        while ((mask_buf[bufpos]))
        {
            val = value_buf[bufpos];
            if (val != "")
            {
                ch = text[bufpos];
                if (!ch)
                {
                    if (fillchar != "") result_buf.push(fillchar);
                    is_filled = false;
                }
                else if (ch == maskchar)
                {
                    ch = char_buf[bufpos];
                    if (ch && ch == maskchar)
                    {
                        result_buf.push(ch);
                    }
                    else
                    {
                        if (fillchar != "") result_buf.push(fillchar);
                        is_filled = false;
                    }
                }
                else if (ch == '*' && val[0] == '*')
                {
                    ch = char_buf[bufpos];
                    if (ch)
                    {
                        result_buf.push(ch);
                    }
                    else
                    {
                        if (fillchar != "") result_buf.push(fillchar);
                        is_filled = false;
                    }
                }
                else
                {
                    result_buf.push(ch);
                }
            }
            bufpos++;
        }
        this._is_filled = is_filled;

        return result_buf.join('');
    };

    _pMaskTypeString.keyPressed = function (ch, pos)
    {
        this._char_buf[pos] = ch;
    };

    _pMaskTypeString.findNearEditablePos = function (pos, direction)
    {
        var value_buf = this._value_buf;
        var ch, len = value_buf.length;

        if (direction > 0)
        {
            if (pos == len)
            {
                return pos;
            }
            else
            {
                while (pos < len)
                {
                    ch = value_buf[pos];
                    if (ch != "") return pos;
                    pos++;
                }
            }
        }
        else if (direction < 0)
        {
            while (pos > -1)
            {
                ch = value_buf[pos];
                if (ch != "") return pos;
                pos--;
            }
        }
        else
        {
            if ((value_buf[pos])) return pos;
        }
        return -1;
    };

    _pMaskTypeString.isDeletableChar = function (ch, pos)
    {
        if (this._value_buf[pos])
            return true;
        return false;
    };

    _pMaskTypeString.isFilterChar = function (ch, pos)
    {
        var mask = this._mask_buf[pos];
        if (mask && typeof mask != "string" && mask.test(ch))
            return false;
        return true;
    };

    _pMaskTypeString.isFilled = function ()
    {
        return this._is_filled;
    };

    //delete _pMaskTypeString;
    _pMaskTypeString = null;

    //===============================================================
    // nexacro._EditMaskTypeDate : 
    // description : object for Calendar's type property
    //===============================================================
    nexacro._EditMaskTypeDate = function ()
    {
        nexacro._EditMaskType.call(this);

        this.maskchar = " ";
        this.date = "";
        this.editmask = "";
        this.editmask_logical = "";
        this.datemask = "";

        this._cnt_editformat_year = 0;
        this._cnt_editformat_month = 0;
        this._cnt_editformat_day = 0;
        this._cnt_editformat_hour = 0;
        this._cnt_editformat_minute = 0;
        this._cnt_editformat_second = 0;

        this._input_mode = "number";
        this._is_filled = false;
        this._use_edit_buf = true;

        this._init();
    };
    var _pMaskTypeDate = nexacro._createPrototype(nexacro._EditMaskType, nexacro._EditMaskTypeDate);
    nexacro._EditMaskTypeDate.prototype = _pMaskTypeDate;
    _pMaskTypeDate._type_name = "MaskTypeDate";

    _pMaskTypeDate._dateformatMap = [["yyyy", "yy"], ["MM", "M", "MMMM", "MMM"], ["dd", "d"], ["HH", "H", "hh", "h"], ["mm", "m"], ["ss", "s"], ["sss"], ["ddd", "dddd"]];

    _pMaskTypeDate._DateTypeConst = {
        DATE: 0,
        TIME: 1,
        DATETIME: 2
    };

    _pMaskTypeDate._DateFormatConst = {
        YEAR: ["yyyy", "yy"],
        MONTH: ["MM", "M", "MMMM", "MMM"],
        DAY: ["dd", "d"],
        HOUR: ["HH", "H", "hh", "h"],
        MINUTE: ["mm", "m"],
        SECOND: ["ss", "s"],
        MILLISECOND: ["sss"],
        DAYOFWEEK: ["ddd", "dddd"],

        NORMALFORMAT_DATE: ["YEAR", "MONTH", "DAY"],
        NORMALFORMAT_TIME: ["HOUR", "MINUTE", "SECOND", "MILLISECOND"],
        NORMALFORMAT_DATETIME: ["YEAR", "MONTH", "DAY", "HOUR", "MINUTE", "SECOND", "MILLISECOND"]
    };

    _pMaskTypeDate._init = function ()
    {
        this.locale = "";
        this._datelistS = ["일", "월", "화", "수", "목", "금", "토"];
        this._datelistL = ["일요일", "월요일", "화요일", "수요일", "목요일", "금요일", "토요일"];
        this._monthlistS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

        this._initdate();
        this._initeditmask();
        this._initdatemask();
    };

    _pMaskTypeDate._initdate = function ()
    {
        this._date = [];
        this._dateObj = null;
    };

    _pMaskTypeDate._initeditmask = function ()
    {
        this._editmask_type = -1;
        this._editmasked_empty_text = "";

        this._editmask = [];
        this._edit_char_buf = [];
        this._edit_value_buf = [];
        this._edit_mask_buf = [];
        this._edit_type_buf = [];
    };

    _pMaskTypeDate._initdatemask = function ()
    {
        this._datemask_type = -1;
        this._datemasked_empty_text = "";

        this._datemask = [];
        this._date_char_buf = [];
        this._date_value_buf = [];
        this._date_mask_buf = [];
        this._date_type_buf = [];
    };

    _pMaskTypeDate.setInputMode = function (mode)
    {
        this._input_mode = mode;
    };

    _pMaskTypeDate.setUseEditBuffer = function (use)
    {
        this._use_edit_buf = use;
    };

    _pMaskTypeDate.setDate = function (date)
    {
        this.date = date;
    };

    _pMaskTypeDate._parseDate = function (date)
    {
        this._initdate();

        if (!date) return;

        var info = this._date;

        var y, M, d;
        switch (this._is_editing ? this.getEditFormatType() : this.getDateFormatType())
        {
            case 0:
                y = date.substr(0, 4);
                M = date.substr(4, 2);
                d = date.substr(6, 2);

                info.push(y);
                info.push(M);
                info.push(d);
                break;
            case 1:
                y = "0000";
                M = "01";
                d = "01";

                info.push(y);
                info.push(M);
                info.push(d);
                info.push(date.substr(0, 2));
                info.push(date.substr(2, 2));
                info.push(date.substr(4, 2));
                info.push(date.substr(6, 3));

                break;
            case 2:
                y = date.substr(0, 4);
                M = date.substr(4, 2);
                d = date.substr(6, 2);

                info.push(y);
                info.push(M);
                info.push(d);
                info.push(date.substr(8, 2));
                info.push(date.substr(10, 2));
                info.push(date.substr(12, 2));
                info.push(date.substr(14, 3));
                break;
        }

        this._dateObj = new Date(y, +M - 1, d);

        (function (_y, _obj)
        {
            if (_y <= 99 && _y >= 0)
            {

                var base_date = new Date(0, 0, 1);
                var base_fullyear = base_date.getFullYear();
                var fullyear = _obj.getFullYear();
                var calc_year = fullyear - base_fullyear;

                _obj.setFullYear(calc_year);
            }

        })(y, this._dateObj);

    };

    _pMaskTypeDate.setEditMask = function (mask)
    {
        if (this.editmask != mask)
        {
            this.editmask_logical = "";
            this._cnt_editformat_month = 0;
            this._cnt_editformat_day = 0;
            this._cnt_editformat_hour = 0;
            this._cnt_editformat_minute = 0;
            this._cnt_editformat_second = 0;

            this.editmask = mask;

            this._parseEditMask(mask);

            if (this.date)
            {
                this._parseDate(this.date);
            }

            var cur_mask, cur_type;
            for (var i = 0, len = this._editmask.length; i < len; i++)
            {
                cur_mask = this._editmask[i].mask
                cur_type = this.changeTypeToDate(this._editmask[i].type);

                switch (cur_type)
                {
                    case "YEAR": this._cnt_editformat_year = cur_mask.length; break;
                    case "MONTH": this._cnt_editformat_month = cur_mask.length; break;
                    case "DAY": this._cnt_editformat_day = cur_mask.length; break;
                    case "HOUR": this._cnt_editformat_hour = cur_mask.length; break;
                    case "MINUTE": this._cnt_editformat_minute = cur_mask.length; break;
                    case "SECOND": this._cnt_editformat_second = cur_mask.length; break;
                }
            }
        }
    };

    _pMaskTypeDate._parseEditMask = function (mask)
    {
        this._initeditmask();

        if (!mask) return;

        if (mask == "SHORTDATE" || mask == "LONGDATE")
        {
            var locale = this._getLocale();
            mask = nexacro.Locale._makeDateMaskString(locale, mask);
        }

        var maskchar = this.maskchar;
        var mask_buf = this._edit_mask_buf;
        var value_buf = this._edit_value_buf;
        var type_buf = this._edit_type_buf;
        var empty_buf = [];
        var cur_buf;

        var info = this._editmask;
        var ch, str, next_ch;
        var type;
        var updateinfos = [];
        var updateinfo = {};
        var bApostrophe = false;
        var bDateMask = false;
        var bTimeMask = false;
        var pos = 0, idx = 0;

        // TODO : ddd 에대한 처리
        do
        {
            ch = mask[pos];
            if (this.isMaskChar(ch) && !bApostrophe)
            {
                if (!str)
                {
                    //start
                    str = ch;
                    idx = pos;
                }
                else
                {
                    if (ch == mask[pos - 1])
                    {
                        str += ch;
                    }
                    else
                    {
                        type = this.changeMaskToType(str);
                        info.push({ mask: str, type: type });

                        for (idx; idx < pos; idx++)
                        {
                            if (str == "dddd" || str == "MMMM" || str == "MMM")
                            {
                                mask_buf[idx] = str[0];
                                value_buf[idx] = "";
                            }
                            type_buf[idx] = type;
                        }
                        str = ch;
                        idx = pos;
                    }
                }

                empty_buf.push(maskchar);
                value_buf.push('$1');
                mask_buf.push(/\d/);

                next_ch = mask[pos + 1];
                if (str.length == 1 && this.isMaskChar(next_ch) && ch != next_ch)
                {
                    type = this.changeMaskToType(str);
                    info.push({ mask: str, type: type });

                    if ((type >= 10 && type <= 69) && ((type % 10) > 0))
                    {
                        updateinfos.push({ pos: pos + 1, type: type });
                    }

                    for (idx; idx < pos + 1; idx++)
                    {
                        if (str == "dddd" || str == "MMMM" || str == "MMM")
                        {
                            mask_buf[idx] = str[0];
                            value_buf[idx] = "";
                        }
                        type_buf[idx] = type;
                    }

                    str = "";
                }
            }
            else
            {
                if (str)
                {
                    type = this.changeMaskToType(str);
                    info.push({ mask: str, type: type });

                    if ((type >= 10 && type <= 69) && ((type % 10) > 0))
                    {
                        updateinfos.push({ pos: pos, type: type });
                    }

                    for (idx; idx < pos; idx++)
                    {
                        if (str == "dddd" || str == "MMMM" || str == "MMM")
                        {
                            mask_buf[idx] = str[0];
                            value_buf[idx] = "";
                        }
                        type_buf[idx] = type;
                    }
                }
                else if (ch == "'" && bApostrophe)
                {
                    bApostrophe = false;
                    continue;
                }
                else if (ch == "'" && !bApostrophe)
                {
                    bApostrophe = true;
                    continue;
                }

                if (!nexacro._isNull(ch))
                {
                    info.push({ mask: ch, type: -1 });

                    empty_buf.push(ch);
                    value_buf.push('');
                    mask_buf.push(ch);
                    type_buf.push(-1);
                }

                str = "";
            }

            if (type >= 0 && type <= 29)
            {
                bDateMask = true;
            }
            if (type >= 30 && type <= 69)
            {
                bTimeMask = true;
            }
        }
        while (mask[pos++]);

        for (var i = updateinfos.length - 1; i >= 0; i--)
        {
            updateinfo = updateinfos[i];
            mask_buf.splice(updateinfo.pos, 0, /\d/);
            type_buf.splice(updateinfo.pos, 0, updateinfo.type);
            value_buf.splice(updateinfo.pos, 0, "$1");
            empty_buf.splice(updateinfo.pos, 0, maskchar);
        }

        if (bDateMask)
        {
            if (bTimeMask)
            {
                this._editmask_type = 2;
            }
            else
            {
                this._editmask_type = 0;
            }
        }
        else
        {
            if (bTimeMask)
            {
                this._editmask_type = 1;
            }
            else
            {
                this._editmask_type = -1;
            }
        }

        this._editmasked_empty_text = empty_buf.join('');

        this.editmask_logical = "";
        for (i = 0; i < type_buf.length; i++)
        {
            cur_buf = type_buf[i];

            if (cur_buf >= 0 && cur_buf < 10)
            {
                this.editmask_logical += "y";
            }
            else if (cur_buf >= 10 && cur_buf < 20)
            {
                this.editmask_logical += "M";
            }
            else if (cur_buf >= 20 && cur_buf < 30)
            {
                this.editmask_logical += "d";
            }
            else if (cur_buf >= 30 && cur_buf < 40)
            {
                this.editmask_logical += "H";
            }
            else if (cur_buf >= 40 && cur_buf < 50)
            {
                this.editmask_logical += "m";
            }
            else if (cur_buf >= 50 && cur_buf < 60)
            {
                this.editmask_logical += "s";
            }
            else
            {
                this.editmask_logical += mask_buf[i];
            }
        }
    };

    _pMaskTypeDate.setDateMask = function (mask)
    {
        if (this.datemask != mask)
        {
            this.datemask = mask;
            this._parseDateMask(this.datemask);
        }
    };

    _pMaskTypeDate._parseDateMask = function (mask)
    {
        this._initdatemask();

        if (!mask) return;

        if (mask == "SHORTDATE" || mask == "LONGDATE")
        {
            var locale = this._getLocale();
            mask = nexacro.Locale._makeDateMaskString(locale, mask);
        }

        var maskchar = this.maskchar;
        var mask_buf = this._date_mask_buf;
        var value_buf = this._date_value_buf;
        var type_buf = this._date_type_buf;
        var empty_buf = [];

        var info = this._datemask;
        var ch, str;
        var type;
        var bApostrophe = false;
        var bDateMask = false;
        var bTimeMask = false;
        var pos = 0, idx = 0;

        do
        {
            ch = mask[pos];
            if (this.isMaskChar(ch) && !bApostrophe)
            {
                if (!str)
                {
                    //start
                    str = ch;
                    idx = pos;
                }
                else
                {
                    if (ch == mask[pos - 1])
                    {
                        str += ch;
                    }
                    else
                    {
                        type = this.changeMaskToType(str);
                        info.push({ mask: str, type: type });

                        for (idx; idx < pos; idx++)
                        {
                            type_buf[idx] = type;
                        }
                        str = ch;
                        idx = pos;
                    }
                }

                empty_buf.push(maskchar);
                value_buf.push('$1');
                mask_buf.push(/\d/);
            }
            else
            {
                if (str)
                {
                    type = this.changeMaskToType(str);
                    info.push({ mask: str, type: type });

                    for (idx; idx < pos; idx++)
                    {
                        type_buf[idx] = type;
                    }
                }
                else if (ch == "'" && bApostrophe)
                {
                    bApostrophe = false;
                    continue;
                }
                else if (ch == "'" && !bApostrophe)
                {
                    bApostrophe = true;
                    continue;
                }

                if (!nexacro._isNull(ch))
                {
                    info.push({ mask: ch, type: -1 });

                    empty_buf.push(ch);
                    value_buf.push('');
                    mask_buf.push(ch);
                    type_buf.push(-1);
                }

                str = "";
            }

            if (type >= 0 && type <= 29)
            {
                bDateMask = true;
            }
            if (type >= 30 && type <= 69)
            {
                bTimeMask = true;
            }
        }
        while (mask[pos++]);

        if (bDateMask)
        {
            if (bTimeMask)
            {
                this._datemask_type = 2;
            }
            else
            {
                this._datemask_type = 0;
            }
        }
        else
        {
            if (bTimeMask)
            {
                this._datemask_type = 1;
            }
            else
            {
                this._datemask_type = -1;
            }
        }

        this._datemasked_empty_text = empty_buf.join('');
    };

    _pMaskTypeDate.setLocale = function (locale)
    {
        this.locale = locale;

        var locale_info = nexacro.Locale.getLocaleInfo(locale);

        this._datelistS = locale_info.weekday_names_short;
        this._datelistL = locale_info.weekday_names_long;
        this._monthlistS = locale_info.month_names_short;
        this._monthlistL = locale_info.month_names_long;

        this._parseEditMask(this.editmask);
        this._parseDateMask(this.datemask);
    };

    _pMaskTypeDate.applyMask = function (value)
    {
        if (!this.datemask || !this.editmask)
            return value;

        value = nexacro._toString(value);

        if (this.date != value)
        //if (this._default_value != value)
        {
            this.setDate(value);
        }

        this._parseDate(this.date);

        if (this._is_editing)
        {
            this._edit_char_buf = [];
        }

        if (!value)
        {
            if (this._is_editing)
                return this._editmasked_empty_text;
            else
                return this._datemasked_empty_text;
        }

        var pos = 0;
        var info, mask, type;
        var infos = this._is_editing ? this._editmask : this._datemask;
        var tmpStr = "";
        var resultStr = "";

        while (info = infos[pos])
        {
            mask = info.mask;
            type = info.type;
            if (type >= 0)
            {
                tmpStr = this._appliedMaskString(info);

                if (this._is_editing)
                {
                    if (type == 13 || type == 12 || type == 70 || type == 71)
                    {
                        tmpStr = mask;
                    }
                    else if (type > 10 && type < 69)
                    {
                        tmpStr = tmpStr.length == 1 ? " " + tmpStr : tmpStr;
                    }
                }
            }
            else
            {
                tmpStr = mask;
            }

            resultStr += tmpStr;

            if (this._is_editing)
            {
                this._edit_char_buf = this._edit_char_buf.concat(tmpStr.split(''));
            }

            pos++;
        }

        return resultStr;
    };

    _pMaskTypeDate.applyMaskEx = function (value)
    {
        if (!this.datemask || !this.editmask)
            return value;

        value = nexacro._toString(value);

        if (!value)
        {
            if (this._is_editing)
                return this._editmasked_empty_text;
            else
                return this._datemasked_empty_text;
        }

        if (this.date != value)
        //if (this._default_value != value)
        {
            this.setDate(value);
        }

        this._parseDate(this.date);

        if (this._is_editing)
        {
            this._edit_char_buf = [];
        }

        var pos = 0;
        var info, mask, type;
        var infos = this._editmask.slice();
        var tmpStr = "";
        var resultStr = "";

        for (var i = 0, len = infos.length; i < len; i++)
        {
            if (infos[i].mask == "M")
            {
                infos[i] = { mask: "MM", type: 10 };
            }
            else if (infos[i].mask == "d")
            {
                infos[i] = { mask: "dd", type: 20 };
            }
            else if (infos[i].mask == "H")
            {
                infos[i] = { mask: "HH", type: 30 };
            }
            else if (infos[i].mask == "m")
            {
                infos[i] = { mask: "mm", type: 40 };
            }
        }

        while (info = infos[pos])
        {
            mask = info.mask;
            type = info.type;
            if (type >= 0)
            {
                tmpStr = this._appliedMaskString(info);

                if (this._is_editing)
                {
                    if (type == 12 || type == 70 || type == 71)
                    {
                        tmpStr = mask;
                    }
                    else if (type > 10 && type < 69)
                    {
                        tmpStr = tmpStr.length == 1 ? " " + tmpStr : tmpStr;
                    }
                }
            }
            else
            {
                tmpStr = mask;
            }

            resultStr += tmpStr;

            if (this._is_editing)
            {
                this._edit_char_buf = this._edit_char_buf.concat(tmpStr.split(''));
            }

            pos++;
        }

        return resultStr;
    };

    _pMaskTypeDate.applyMaskSpin = function (caretPos, diff)
    {
        var editmask = this._editmask;
        var type_buf = this._edit_type_buf.slice(0);
        var char_buf = this._edit_char_buf;

        caretPos = (caretPos == type_buf.length) ? caretPos - 1 : caretPos;
        var caretType = type_buf[caretPos];
        if (caretType == -1)
        {
            caretPos = caretPos > 0 ? caretPos - 1 : caretPos;
            caretType = type_buf[caretPos];
            if (caretType == -1)
            {
                return char_buf.join('');
            }
        }

        var pos = 0;
        var type = -1;
        var tmpStr = "";
        var changeidx_buf = [];
        var info = {};
        while (!nexacro._isNull(type = type_buf[pos]))
        {
            if (caretType == type)
            {
                tmpStr += char_buf[pos];
                changeidx_buf.push(pos);
            }
            if (editmask[pos] && editmask[pos].type == caretType)
            {
                info = editmask[pos];
            }
            pos++;
        }

        var intVal = +tmpStr + diff;

        switch (caretType)
        {
            case 0:
            case 1:
                if (intVal < 0)
                {
                    intVal = 9999;
                }
                else if (intVal > 9999)
                {
                    intVal = 0;
                }
                break;
            case 10:
            case 11:
                if (intVal < 1)
                {
                    intVal = 12;
                }
                else if (intVal > 12)
                {
                    intVal = 1;
                }
                break;
            case 20:
            case 21:
                var endday = this.getEndDay(this._date[0], this._date[1]);
                if (intVal < 1)
                {
                    intVal = endday;
                }
                else
                {
                    if (intVal > endday)
                    {
                        intVal = 1;
                    }
                }
                break;
            case 30:
            case 31:
                if (intVal < 0)
                {
                    intVal = 23;
                }
                else if (intVal > 23)
                {
                    intVal = 0;
                }
                break;
            case 32:
            case 33:
                if (intVal < 0)
                {
                    intVal = 11;
                }
                else if (intVal > 11)
                {
                    intVal = 0;
                }
                break;
            case 40:
            case 41:
            case 50:
            case 51:
                if (intVal < 0)
                {
                    intVal = 59;
                }
                else if (intVal > 59)
                {
                    intVal = 0;
                }
                break;
            case 60:
                if (intVal < 0)
                {
                    intVal = 999;
                }
                else if (intVal > 999)
                {
                    intVal = 0;
                }
                break;
        }

        var text_buf = [];
        tmpStr = this._appliedMaskString(info, intVal.toString());
        if (caretType > 10 && caretType < 69)
        {
            tmpStr = tmpStr.length == 1 ? " " + tmpStr : tmpStr;
        }
        text_buf = tmpStr.split('');

        for (var i = 0; i < changeidx_buf.length; i++)
        {
            char_buf[changeidx_buf[i]] = text_buf[i];
        }

        return char_buf.join('');
    };

    _pMaskTypeDate.arrangeMask = function (input_text, begin, end, end_sel)
    {
        var mask_buf = this._edit_mask_buf;
        var value_buf = this._edit_value_buf;
        var char_buf = this._edit_char_buf;

        var mask_len = mask_buf.length;
        if (mask_len == 0)
            return { "text": input_text, "pos": end };

        var text = nexacro._toString(input_text);
        var text_buf = text.split('');

        var mask;
        var maskchar = this.maskchar;
        var i, val, over_cnt = (text.length - mask_len);

        for (i = begin; i < end; i++)
        {
            val = value_buf[i];
            if (val == null) break;

            if (val == "")
            {
                if (!isNaN(nexacro.toNumber(text_buf[i])))
                {
                    end++;
                    over_cnt++;
                    text_buf.splice(i, 0, mask_buf[i]);
                }
            }
            else
            {
                mask = mask_buf[i];
                var ch = text_buf[i];

                if (val == "$1" && mask.test(ch))
                {
                    char_buf[i] = ch;
                    text_buf[i] = ch;
                }
                else
                {
                    char_buf[i] = maskchar;
                    text_buf[i] = maskchar;
                }
            }
        }

        if (end < mask_len || over_cnt < mask_len)
        {
            if (over_cnt > 0)
            {
                var start = end_sel && end_sel - begin != 0 ? end_sel : end;
                text_buf.splice(start, over_cnt);
            }
            else if (over_cnt < 0)
            {
                over_cnt = -(over_cnt);
                for (i = 0; i < over_cnt; i++)
                {
                    var pos = end + i;
                    val = value_buf[pos];
                    if (val == "")
                    {
                        text_buf.splice(pos, 0, mask_buf[pos]);
                    }
                    else
                    {
                        text_buf.splice(pos, 0, maskchar);
                        char_buf[pos] = maskchar;
                    }
                }
            }
        }
        else
        {
            end = mask_len;
            text_buf.splice(end, (text_buf.length - end));
        }
        return { "text": text_buf.join(''), "pos": end };
    };

    _pMaskTypeDate.removeMask = function (char_buf, _is_date)
    {
        if (!char_buf)
            char_buf = _is_date ? this._date_char_buf : this._edit_char_buf; // dateformat 기준 제거

        var type_buf = _is_date ? this._date_type_buf : this._edit_type_buf; // dateformat 기준 제거
        var tmp_str = "";
        var result_buf = [];
        var pos = 0, type = 0, ch = "";
        var cur_type = -1, prev_type = -1;

        for (let len = char_buf.length; pos < len; pos++)
        {
            if (char_buf[pos] !== undefined)
                break;
        }

        do
        {
            if (type_buf[pos] > -1)
            {
                cur_type = parseInt(type_buf[pos] / 10);

                if (type_buf[pos - 1] != -1 && type_buf[pos - 1] != type_buf[pos])
                {
                    if (tmp_str !== "")
                    {
                        result_buf[type] = this._getRemoveMaskString(type, tmp_str);
                        tmp_str = "";
                    }
                }

                for (var i = prev_type + 1; i < cur_type; i++)
                {
                    var empty_type = i * 10;
                    result_buf[empty_type] = this._getRemoveMaskString(empty_type, "");
                }
                ch = char_buf[pos] ? char_buf[pos] : "";

                if (tmp_str === "")
                {
                    type = type_buf[pos];
                    prev_type = cur_type;
                }
                tmp_str = tmp_str.concat(ch);
            }
            else
            {
                if (tmp_str !== "")
                {
                    result_buf[type] = this._getRemoveMaskString(type, tmp_str);
                    tmp_str = "";
                }
            }

            pos++;
        }
        while (!nexacro._isNull(type_buf[pos]));

        if (tmp_str !== "")
        {
            result_buf[type] = this._getRemoveMaskString(type, tmp_str);
        }

        return result_buf.join('');
    };

    _pMaskTypeDate.keyPressed = function (ch, pos)
    {
        this._edit_char_buf[pos] = ch;

        var value_buf = this._edit_value_buf;
        var value_len = value_buf.length;
        for (var i = value_len; i > 0; i--)
        {
            if (value_buf[i] && value_buf[i] == "$1")
            {
                break;
            }
        }

        if ((this._edit_char_buf.length == value_len) && (pos == i))
        {
            this._is_filled = true;
        }
        else
        {
            this._is_filled = false;
        }
    };

    _pMaskTypeDate.findNearEditablePos = function (pos, direction)
    {
        var value_buf = this._edit_value_buf;
        var ch, len = value_buf.length;

        if (direction > 0)
        {
            while (pos < len)
            {
                ch = value_buf[pos];
                if (ch != "") return pos;
                pos++;
            }
        }
        else if (direction < 0)
        {
            while (pos > -1)
            {
                ch = value_buf[pos];
                if (ch != "") return pos;
                pos--;
            }
        }
        else
        {
            if (value_buf[pos]) return pos;
        }
        return -1;
    };

    _pMaskTypeDate.isDeletableChar = function (ch, pos)
    {
        if (this._edit_value_buf[pos])
            return true;
        return false;
    };

    _pMaskTypeDate.isFilterChar = function (ch, pos_begin, pos_end, skip_maxday)
    {
        if (!/[0-9]/.test(ch))
            return true;

        var char_buf = this._edit_char_buf.slice(0);

        var nomaskch = ch.replace(/[^0-9]/g, '');

        var buf_len = char_buf.length;
        var i;
        var idx = 0;
        var changed_type;
        var changed_str = "";
        var changed_buf = {};
        var regexp_num = /^[0-9]/;
        if (nomaskch.length > 1)
        {
            for (i = pos_begin; i < buf_len; i++)
            {
                if (idx == nomaskch.length)
                    break;
                if (regexp_num.test(char_buf[i]))
                {
                    char_buf[i] = nomaskch[idx];
                    idx++;
                }
            }
        }
        else
        {
            char_buf[pos_begin] = ch;

            changed_str = ch;
            changed_type = this._edit_type_buf[pos_begin];

            for (i = pos_begin - 1; i >= 0; i--)
            {
                if (changed_type == this._edit_type_buf[i])
                {
                    changed_str = char_buf[i] + changed_str;
                }
                else
                {
                    break;
                }
            }
            for (i = pos_begin + 1; i < char_buf.length; i++)
            {
                if (changed_type == this._edit_type_buf[i])
                {
                    changed_str += char_buf[i];
                }
                else
                {
                    break;
                }
            }

            changed_buf[this.changeTypeToDate(changed_type)] = changed_str;
        }

        if (pos_end && pos_begin < pos_end)
        {
            for (i = (pos_begin + 1); i < pos_end && i < buf_len; i++)
            {
                char_buf[i] = "";
            }
        }

        var val = this.removeMask(char_buf);

        var y, M, d;
        var h, m, s, ss;
        var editmask_type = this.getEditFormatType();

        switch (editmask_type)
        {
            case 0:
                y = val.substr(0, 4);
                M = val.substr(4, 2);
                d = val.substr(6, 2);
                break;
            case 1:
                var n = 8;
                if (this._edit_type_buf[0] < 40)
                {
                    h = val.substr(n, 2);
                    n = 10;
                }
                m = val.substr(n, 2);
                s = val.substr(n + 2, 2);
                ss = val.substr(n + 2, 3);

                break;
            case 2:
                y = val.substr(0, 4);
                M = val.substr(4, 2);
                d = val.substr(6, 2);
                h = val.substr(8, 2);
                m = val.substr(10, 2);
                s = val.substr(12, 2);
                ss = val.substr(14, 3);
                break;
        }

        if ((y && isNaN(y = +y)) || (M && isNaN(M = +M)) || (d && isNaN(d = +d)) ||
            (h && isNaN(h = +h)) || (m && isNaN(m = +m)) || (s && isNaN(s = +s)) || (ss && isNaN(ss = +ss)))
        {
            return true;
        }

        var maxDay = this.getEndDay(y, M);

        if (!skip_maxday &&
            ((editmask_type != 1 && !maxDay) ||
                (M && (+M > 12)) || (d && (+d > maxDay)) ||
                (h && (+h >= 24)) || (m && (+m >= 60)) || (s && (+s >= 60)) || (ss && (+ss >= 1000))))
        {
            return true;
        }

        return false;
    };

    _pMaskTypeDate.isFilterCharEx = function (ch, pos_begin, pos_end)
    {
        var _date = {};
        _date.ret = false;
        _date.date = "";
        _date.pos = pos_begin;

        if (!/[0-9]/.test(ch))
        {
            _date.ret = true;
            return _date;
        }

        var char_buf = this._edit_char_buf.slice(0);

        var nomaskch = ch.replace(/[^0-9]/g, '');

        var buf_len = char_buf.length;
        var i;
        var idx = 0;
        var changed_type;
        var changed_str = "";
        var changed_buf = {};
        var regexp_num = /^[0-9]/;
        if (nomaskch.length > 1)
        {
            for (i = pos_begin; i < buf_len; i++)
            {
                if (idx == nomaskch.length)
                    break;
                if (regexp_num.test(char_buf[i]))
                {
                    char_buf[i] = nomaskch[idx];
                    idx++;
                }
            }
        }
        else
        {
            char_buf[pos_begin] = ch;

            changed_str = ch;
            changed_type = this._edit_type_buf[pos_begin];

            for (i = pos_begin - 1; i >= 0; i--)
            {
                if (changed_type == this._edit_type_buf[i])
                {
                    changed_str = char_buf[i] + changed_str;
                }
                else
                {
                    break;
                }
            }
            for (i = pos_begin + 1; i < char_buf.length; i++)
            {
                if (changed_type == this._edit_type_buf[i])
                {
                    changed_str += char_buf[i];
                }
                else
                {
                    break;
                }
            }

            changed_buf[this.changeTypeToDate(changed_type)] = changed_str;
        }

        var y, M, M1, M2, d, d1, d2;
        var _y;
        var h, h1, h2, m, m1, m2, s, s1, s2, ss, H;
        var editmask_type = this.getEditFormatType();
        var curr_mask = "";

        var _pos_begin = pos_begin;
        var val = this.removeMask(char_buf);

        if (editmask_type != 1)
        {
            var input_val = ch;
            var _msk = this.editmask_logical.substr(pos_begin, 1);

            if (_msk == "M")
            {
                var _msk1 = this.editmask_logical.substr(pos_begin + 1, 1);
                if (_msk1 == "M")
                {
                    if (input_val > 1)
                    {
                        char_buf[pos_begin + 1] = (char_buf[pos_begin + 1] == " " || char_buf[pos_begin + 1] == undefined) ? "0" : char_buf[pos_begin + 1];
                        _pos_begin = pos_begin + 1;
                    }
                }
            }
            else if (_msk == "d")
            {
                y = val.substr(0, 4);
                M = val.substr(4, 2);

                var _maxday = this.getEndDay(y, M);
                if (input_val > _maxday / 10)
                {
                    char_buf[pos_begin + 1] = (char_buf[pos_begin + 1] == " " || char_buf[pos_begin + 1] == undefined) ? "0" : char_buf[pos_begin + 1];
                    _pos_begin = pos_begin + 1;
                }
            }
            else if (_msk == "H")
            {
                y = val.substr(0, 4);
                M = val.substr(4, 2);
                d = val.substr(6, 2);

                var _msk1 = this.editmask_logical.substr(pos_begin + 1, 1);
                if (_msk1 == "H")
                {
                    if (input_val > 2)
                    {
                        char_buf[pos_begin + 1] = (char_buf[pos_begin + 1] == " " || char_buf[pos_begin + 1] == undefined) ? "0" : char_buf[pos_begin + 1];
                        _pos_begin = pos_begin + 1;
                    }
                }
            }
            else if (_msk == "m")
            {
                y = val.substr(0, 4);
                M = val.substr(4, 2);
                d = val.substr(6, 2);
                H = val.substr(8, 2);

                var _msk1 = this.editmask_logical.substr(pos_begin + 1, 1);
                if (_msk1 == "m")
                {
                    if (input_val > 5)
                    {
                        char_buf[pos_begin + 1] = (char_buf[pos_begin + 1] == " " || char_buf[pos_begin + 1] == undefined) ? "0" : char_buf[pos_begin + 1];
                        _pos_begin = pos_begin + 1;
                    }
                }
            }
            else if (_msk == "s")
            {
                y = val.substr(0, 4);
                M = val.substr(4, 2);
                d = val.substr(6, 2);
                H = val.substr(8, 2);
                m = val.substr(10, 2);

                var _msk1 = this.editmask_logical.substr(pos_begin + 1, 1);
                if (_msk1 == "s")
                {
                    if (input_val > 5)
                    {
                        char_buf[pos_begin + 1] = (char_buf[pos_begin + 1] == " " || char_buf[pos_begin + 1] == undefined) ? "0" : char_buf[pos_begin + 1];
                        _pos_begin = pos_begin + 1;
                    }
                }
            }
        }
        else if (editmask_type == 1)
        {
            var input_val = ch;
            var _msk = this.editmask_logical.substr(pos_begin, 1);

            if (_msk == "H")
            {
                var _msk1 = this.editmask_logical.substr(pos_begin, 1);
                if (_msk1 == "H")
                {
                    if (input_val > 2)
                    {
                        char_buf[pos_begin + 1] = (char_buf[pos_begin + 1] == " " || char_buf[pos_begin + 1] == undefined) ? "0" : char_buf[pos_begin + 1];
                        _pos_begin = pos_begin + 1;
                    }
                }
            }
            else if (_msk == "m")
            {
                H = val.substr(8, 2);

                var _msk1 = this.editmask_logical.substr(pos_begin, 1);
                if (_msk1 == "m")
                {
                    if (input_val > 5)
                    {
                        char_buf[pos_begin + 1] = (char_buf[pos_begin + 1] == " " || char_buf[pos_begin + 1] == undefined) ? "0" : char_buf[pos_begin + 1];
                        _pos_begin = pos_begin + 1;
                    }
                }
            }
            else if (_msk == "s")
            {
                H = val.substr(8, 2);
                m = val.substr(10, 2);

                var _msk1 = this.editmask_logical.substr(pos_begin, 1);
                if (_msk1 == "s")
                {
                    if (input_val > 5)
                    {
                        char_buf[pos_begin + 1] = (char_buf[pos_begin + 1] == " " || char_buf[pos_begin + 1] == undefined) ? "0" : char_buf[pos_begin + 1];
                        _pos_begin = pos_begin + 1;
                    }
                }
            }
        }

        if (pos_end && pos_begin < pos_end)
        {
            for (i = (_pos_begin + 1); i < pos_end && i < buf_len; i++)
            {
                char_buf[i] = "";
            }
        }

        val = this.removeMask(char_buf);

        switch (editmask_type)
        {
            case 0:
                y = val.substr(0, 4);
                M = val.substr(4, 2);
                M1 = val.substr(4, 1);
                M2 = val.substr(5, 1);
                d = val.substr(6, 2);
                d1 = val.substr(6, 1);
                d2 = val.substr(7, 1);
                break;
            case 1:
                var n = 8;
                if (this._edit_type_buf[0] < 40)
                {
                    h = val.substr(n, 2);
                    h1 = val.substr(n, 1);
                    h2 = val.substr(n + 1, 1);
                    n = 10;
                }
                m = val.substr(n, 2);
                m1 = val.substr(n, 1);
                m2 = val.substr(n + 1, 1);
                s = val.substr(n + 2, 2);
                s1 = val.substr(n + 2, 1);
                s2 = val.substr(n + 3, 1);
                ss = val.substr(n + 4, 3);
                break;
            case 2:
                y = val.substr(0, 4);
                M = val.substr(4, 2);
                M1 = val.substr(4, 1);
                M2 = val.substr(5, 1);
                d = val.substr(6, 2);
                d1 = val.substr(6, 1);
                d2 = val.substr(7, 1);
                h = val.substr(8, 2);
                h1 = val.substr(8, 1);
                h2 = val.substr(9, 1);
                m = val.substr(10, 2);
                m1 = val.substr(10, 1);
                m2 = val.substr(11, 1);
                s = val.substr(12, 2);
                s1 = val.substr(12, 1);
                s2 = val.substr(13, 1);
                ss = val.substr(14, 3);
                break;
        }

        if ((y && isNaN(_y = +y)) || (M && isNaN(M = +M)) || (d && isNaN(d = +d)) ||
            (h && isNaN(h = +h)) || (m && isNaN(m = +m)) || (s && isNaN(s = +s)) || (ss && isNaN(ss = +ss)))
        {
            _date.ret = true;
            return _date;
        }

        var maxDay = this.getEndDay(y, M);

        if (((editmask_type != 1 && !maxDay) || M === 0 || d === 0 ||
            (M && (+M > 12)) || (d && (+d > maxDay)) ||
            (h && (+h >= 24)) || (m && (+m >= 60)) || (s && (+s >= 60)) || (ss && (+ss >= 1000))))
        {
            _date.ret = true;
            _date.date = y;

            var _mask = this.editmask_logical.substr(pos_begin, 1);
            var _find_pos = false;
            var _add_pos = 0;
            for (var i = pos_begin + 1, len = this.editmask_logical.length; i < len; i++)
            {
                curr_mask = this.editmask_logical[i];
                if (this.isMaskChar(curr_mask) && _mask == curr_mask)
                {
                    _date.pos = i;
                    _find_pos = true;
                }
                else if (this.isMaskChar(curr_mask) && _mask != curr_mask)
                {
                    break;
                }
                else
                {
                    _add_pos++;
                }
            }

            if (!_find_pos)
                _date.pos = i;

            if (_mask == "y")
            {
                if (M)
                    _date.date += (M1 + M2);

                var _maxday = this.getEndDay(y, M);
                if (d > _maxday)
                {
                    _date.date += _maxday;
                }
                else
                {
                    _date.date += (d1 + d2);
                }

                if (h)
                {
                    _date.date += (h1 + h2);
                }

                if (m)
                {
                    _date.date += (m1 + m2);
                }

                if (s)
                {
                    _date.date += (s1 + s2);
                }
            }
            else if (_mask == "M")
            {
                var _M = M;

                var _mask1 = this.editmask_logical.substr(pos_begin + 1, 1);

                if (+M == 0)
                {
                    if (this._cnt_editformat_month == 2)
                        _date.date += ("0" + " ");
                    else
                        _date.date += (" " + " ");
                }
                else if (+M > 12)
                {
                    if (M1 > 1)
                    {
                        if (this._cnt_editformat_month == 2)
                            _date.date += ("0" + M1);
                        else
                            _date.date += (" " + M1);

                        _date.pos += _add_pos + 1;
                        _M = M1;
                    }
                    else
                    {
                        if (this._cnt_editformat_month == 2)
                        {
                            if (_mask1 == "M")
                            {
                                _date.date += (M1 + " ");
                                _date.pos = pos_begin + 1;
                                _M = M1;
                            }
                            else // 두번째 M 수정 시 일때
                            {
                                _date.date += ("0" + M2);
                                _M = M2;
                            }
                        }
                        else // format 이 MM 이 아닐 경우
                        {
                            if (M1 == ch)
                            {
                                _date.date += (M1 + " ");
                                _date.pos = pos_begin + 1;
                                _M = M1;
                            }
                            else
                            {
                                _date.date += (" " + M2);
                                _date.pos = pos_begin + 2;
                                _M = M2;
                            }
                        }
                    }
                }
                else if (+M >= 10)
                {
                    _date.date += M;
                }
                else if (+M >= 1)
                {
                    if (_mask1 == "M")
                    {
                        if (this._cnt_editformat_month == 2)
                            _date.date += ("0" + M1);
                        else
                            _date.date += (" " + M1);
                    }
                    else
                    {
                        if (this._cnt_editformat_month == 2)
                            _date.date += ("0" + M2);
                        else
                            _date.date += (" " + M2);
                    }
                }

                var _maxday = this.getEndDay(y, _M);
                if (d > _maxday)
                {
                    _date.date += _maxday;
                }
                else
                {
                    if (this._cnt_editformat_day == 2)
                    {
                        _date.date += (d1 + d2);
                    }
                    else
                    {
                        if (d && d < 10)
                        {
                            _date.date += (" " + d2);
                        }
                        else
                        {
                            _date.date += (d1 + d2);
                        }
                    }
                }

                if (h)
                {
                    _date.date += (h1 + h2);
                }

                if (m)
                {
                    _date.date += (m1 + m2);
                }

                if (s)
                {
                    _date.date += (s1 + s2);
                }
            }

            else if (_mask == "d")
            {
                if (M)
                {
                    if (this._cnt_editformat_month == 2)
                    {
                        _date.date += (M1 + M2);
                    }
                    else
                    {
                        if (M < 10)
                        {
                            _date.date += (" " + M2);
                        }
                        else
                        {
                            _date.date += (M1 + M2);
                        }
                    }
                }

                if (d && (+d > maxDay))
                {
                    if (d1 > maxDay / 10)
                    {
                        if (this._cnt_editformat_day == 2)
                            _date.date += ("0" + d1);
                        else
                            _date.date += (" " + d1);

                        _date.pos += _add_pos + 1;
                    }
                    else
                    {
                        if (this._cnt_editformat_day == 2)
                        {
                            //var _mask1 = this._cnt_editformat_month == 1 ? this.editmask.substr(pos_begin, 1) : this.editmask.substr(pos_begin + 1, 1);
                            var _mask1 = this.editmask_logical.substr(pos_begin + 1, 1);

                            if (_mask1 == "d")
                            {
                                _date.date += (d1 + " ");
                                _date.pos = pos_begin + 1;
                            }
                            else
                            {
                                _date.date += ("0" + d2);
                            }
                        }
                        else
                        {
                            if (curr_mask == "d" && d1 == ch)
                            {
                                _date.date += (d1 + " ");
                            }
                            else
                            {
                                _date.date += (" " + d2);
                            }
                        }
                    }
                }
                else if (d == 0)
                {
                    if (this._cnt_editformat_day == 2)
                        _date.date += ("0" + " ");
                    else
                        _date.date += (" " + " ");
                }

                if (h)
                {
                    _date.date += (h1 + h2);
                }

                if (m)
                {
                    _date.date += (m1 + m2);
                }

                if (s)
                {
                    _date.date += (s1 + s2);
                }
            }
            else if (_mask == "H")
            {
                if (!_date.date)
                    _date.date = "";

                if (M)
                {
                    if (this._cnt_editformat_month == 2)
                    {
                        _date.date += (M1 + M2);
                    }
                    else
                    {
                        if (M < 10)
                        {
                            _date.date += (" " + M2);
                        }
                        else
                        {
                            _date.date += (M1 + M2);
                        }
                    }
                }

                if (d)
                {
                    if (this._cnt_editformat_day == 2)
                    {
                        _date.date += (d1 + d2);
                    }
                    else
                    {
                        if (d < 10)
                        {
                            _date.date += (" " + d2)
                        }
                        else
                        {
                            _date.date += (d1 + d2);
                        }
                    }
                }

                var _h = h;
                if (h && (+h >= 24))
                {
                    if (h1 > 2)
                    {
                        if (this._cnt_editformat_hour == 2)
                        {
                            _date.date += ("0" + h1);
                        }
                        else
                        {
                            _date.date += (" " + h1);
                        }

                        _date.pos += _add_pos + 1;
                        _h = h1;
                    }
                    else
                    {
                        if (this._cnt_editformat_hour == 2)
                        {
                            //var _mask1 = this.editmask.substr(pos_begin + 1, 1);
                            var _mask1 = this.editmask_logical.substr(pos_begin + 1, 1);
                            if (_mask1 == "H")
                            {
                                _date.date += (h1 + " ");
                                _date.pos = pos_begin + 1;
                                _h = h1;
                            }
                            else // 두번째 M 수정 시 일때
                            {
                                _date.date += ("0" + h2);
                                _h = h2;
                            }
                        }
                        else
                        {
                            if (h1 == ch)
                            {
                                _date.date += (h1 + " ");
                                _date.pos = pos_begin + 1;
                                _h = h1;
                            }
                            else
                            {
                                _date.date += (" " + h2);
                                _date.pos = pos_begin + 2;
                                _h = h2;
                            }
                        }
                    }
                }

                if (m)
                {
                    _date.date += (m1 + m2);
                }

                if (s)
                {
                    _date.date += (s1 + s2);
                }
            }
            else if (_mask == "m")
            {
                if (!_date.date)
                    _date.date = "";

                if (M)
                {
                    if (this._cnt_editformat_month == 2)
                    {
                        _date.date += (M1 + M2);
                    }
                    else
                    {
                        if (M < 10)
                        {
                            _date.date += (" " + M2);
                        }
                        else
                        {
                            _date.date += (M1 + M2);
                        }
                    }
                }

                if (d)
                {
                    if (this._cnt_editformat_day == 2)
                    {
                        _date.date += (d1 + d2);
                    }
                    else
                    {
                        if (d < 10)
                        {
                            _date.date += (" " + d2)
                        }
                        else
                        {
                            _date.date += (d1 + d2);
                        }
                    }
                }

                if (h !== undefined)
                {
                    _date.date += (h1 + h2);
                }

                var _m = m;
                if (m && (+m >= 60))
                {
                    if (m1 > 5)
                    {
                        if (this._cnt_editformat_minute == 2)
                        {
                            _date.date += ("0" + m1);
                        }
                        else
                        {
                            _date.date += (" " + m1);
                        }

                        _date.pos += _add_pos + 1;
                        _m = m1;
                    }
                }

                if (s)
                {
                    _date.date += (s1 + s2);
                }
            }

            else if (_mask == "s")
            {
                if (!_date.date)
                    _date.date = "";

                if (M)
                {
                    if (this._cnt_editformat_month == 2)
                    {
                        _date.date += (M1 + M2);
                    }
                    else
                    {
                        if (M < 10)
                        {
                            _date.date += (" " + M2);
                        }
                        else
                        {
                            _date.date += (M1 + M2);
                        }
                    }
                }

                if (d)
                {
                    if (this._cnt_editformat_day == 2)
                    {
                        _date.date += (d1 + d2);
                    }
                    else
                    {
                        if (d < 10)
                        {
                            _date.date += (" " + d2)
                        }
                        else
                        {
                            _date.date += (d1 + d2);
                        }
                    }
                }

                if (h)
                {
                    _date.date += (h1 + h2);
                }

                if (m)
                {
                    _date.date += (m1 + m2);
                }

                if (s && (+s >= 60))
                {
                    if (s1 > 5)
                    {
                        if (this._cnt_editformat_second == 2)
                        {
                            _date.date += ("0" + s1);
                        }
                        else
                        {
                            _date.date += (" " + s1);
                        }
                        _date.pos += _add_pos + 1;
                    }
                }
            }

            return _date;
        }

        return false;
    };

    _pMaskTypeDate.isFilled = function ()
    {
        return this._is_filled;
    };

    _pMaskTypeDate.isMaskChar = function (ch)
    {
        if (ch == "y" || ch == "M" || ch == "d" || ch == "H" || ch == "h" || ch == "m" || ch == "s")
        {
            return true;
        }
        return false;
    };

    _pMaskTypeDate.isMaskString = function (str)
    {
        if (str === "yyyy" || str === "yy" || str === "MMMM" || str === "MMM" || str === "MM" || str === "M" || str === "dddd" || str === "ddd" || str === "dd" || str === "d")
        {
            return true;
        }
        return false;
    };

    _pMaskTypeDate.getEditFormatType = function ()
    {
        return this._editmask_type;
    };

    _pMaskTypeDate.getEditFormatStringType = function ()
    {
        for (var i in this._DateTypeConst)
        {
            if (this._DateTypeConst[i] == this._editmask_type)
            {
                break;
            }
        }
        return i;
    };

    _pMaskTypeDate.getDateFormatType = function ()
    {
        return this._datemask_type;
    };

    _pMaskTypeDate.getCurrentText = function ()
    {
        return this._edit_char_buf.join('');
    };

    _pMaskTypeDate.getEmptyText = function ()
    {
        if (this._is_editing)
        {
            return this._editmasked_empty_text;
        }
        else
        {
            return this._datemasked_empty_text;
        }
    };

    _pMaskTypeDate.getDatePickerValue = function ()
    {
        var date = this._date;
        if (date.length == 0)
        {
            var currentDate = new Date();
            var year = nexacro._toString(currentDate.getFullYear()).padLeft(4, "0");
            var month = nexacro._toString(currentDate.getMonth() + 1).padLeft(2, "0");
            var day = nexacro._toString(currentDate.getDate()).padLeft(2, "0");

            return year + month + day;
        }
        else
        {
            return date[0] + date[1] + date[2];
        }
    };

    _pMaskTypeDate.getCurrentDate = function ()
    {
        var year, month, day;
        var currDate = new Date();

        year = currDate.getFullYear();
        month = currDate.getMonth() + 1;
        day = currDate.getDate();

        return { year: year, month: month, day: day };
    };

    _pMaskTypeDate.getEndDay = function (y, m)
    {
        var endDayN = new Array(31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31);
        var endDayL = new Array(31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31);

        var ret = "";
        var year = +y;
        var month = +m;

        if (isNaN(year) || isNaN(month))
        {
            return;
        }

        if (month == 0)
            month = 1;

        if (year == 0)
        {
            ret = endDayN[month - 1];
            return ret;
        }

        if ((year % 4) == 0 && (year % 100) != 0 || (year % 400) == 0)
        {
            ret = endDayL[month - 1];
        }
        else
        {
            ret = endDayN[month - 1];
        }
        //endDayN = endDayL = null;
        return ret;
    };

    _pMaskTypeDate.changeNormalizeValue = function (v)
    {
        if (v instanceof nexacro.Date)
        {
            v = v.toString();
        }

        if (nexacro._isNull(v) || v === "" || v.trim() === "")
        {
            return v;
        }

        var y, M, d;
        var h, m, s, ss;
        var str = "";
        var editformattype = this.getEditFormatType();
        switch (editformattype)
        {
            case 0:
                y = v.substr(0, 4);
                M = v.substr(4, 2) || "01";
                d = v.substr(6, 2) || "01";
                break;
            case 1:
                y = "0000";
                M = "01";
                d = "01";
                h = v.substr(0, 2);
                m = v.substr(2, 2);
                s = v.substr(4, 2);
                ss = v.substr(6, 3);
                break;
            case 2:
                y = v.substr(0, 4);
                M = v.substr(4, 2) || "01";
                d = v.substr(6, 2) || "01";
                h = v.substr(8, 2);
                m = v.substr(10, 2);
                s = v.substr(12, 2);
                ss = v.substr(14, 3);
                break;
            default:
                return v;
        }

        if (!nexacro._isNull(y)) y = y.padLeft(4, "0");
        if (!nexacro._isNull(M))
        {
            M = M.padLeft(2, "0");
            M -= 1;
        }
        if (!nexacro._isNull(d)) d = d.padLeft(2, "0");
        if (!nexacro._isNull(h)) h = h.padLeft(2, "0");
        if (!nexacro._isNull(m)) m = m.padLeft(2, "0");
        if (!nexacro._isNull(s)) s = s.padLeft(2, "0");
        if (!nexacro._isNull(ss)) ss = ss.padLeft(3, "0");

        var date = new nexacro.Date(y, M, d, h, m, s, ss);

        if (editformattype == 1) date._timeonly = true;

        str = date.toString();

        return str;
    };

    _pMaskTypeDate.changeNormalizeValueFromBuffer = function ()
    {
        var i = 0;
        var j, date_obj;
        var y, M, d, h, m, s, ms;

        var edit_datetype;
        var normal_datetype;

        var edit_formattype = this.getEditFormatStringType();
        var normal_format = this._DateFormatConst["NORMALFORMAT_" + edit_formattype].concat();

        var edit_char_buf = this._edit_char_buf;
        var edit_type_buf = this._edit_type_buf;

        var before_idx = -1;
        var curr_idx = -1;

        var curr_date = this._date;

        // 현재 입력되어있는 문자열을 날짜 변수에 할당
        while (i <= edit_type_buf.length)
        {
            edit_datetype = this.changeTypeToDate(edit_type_buf[i]);

            before_idx = curr_idx;
            curr_idx = normal_format.indexOf(edit_datetype);

            if (before_idx >= 0 && before_idx != curr_idx)
            {
                delete normal_format[before_idx];
            }

            if (curr_idx >= 0)
            {
                if (edit_datetype == "YEAR") { if (!y) y = ""; y += edit_char_buf[i] ? edit_char_buf[i] : "" }
                if (edit_datetype == "MONTH") { if (!M) M = ""; M += edit_char_buf[i] ? edit_char_buf[i] : "" }
                if (edit_datetype == "DAY") { if (!d) d = ""; d += edit_char_buf[i] ? edit_char_buf[i] : "" }
                if (edit_datetype == "HOUR") { if (!h) h = ""; h += edit_char_buf[i] ? edit_char_buf[i] : "" }
                if (edit_datetype == "MINUTE") { if (!m) m = ""; m += edit_char_buf[i] ? edit_char_buf[i] : "" }
                if (edit_datetype == "SECOND") { if (!s) s = ""; s += edit_char_buf[i] ? edit_char_buf[i] : "" }
                if (edit_datetype == "MILLISECOND") { if (!ms) ms = ""; ms += edit_char_buf[i] ? edit_char_buf[i] : "" }
            }

            i++;
        }

        // 남은 정규포맷을 날짜 변수에 할당. date값이 있으면 date값으로 하고, 없으면 기본값
        while (normal_format.length > 0)
        {
            normal_datetype = normal_format.pop();

            if (normal_datetype)
            {
                if (normal_datetype == "YEAR") y = curr_date[0] ? curr_date[0] : "0000";
                if (normal_datetype == "MONTH") M = curr_date[1] ? curr_date[1] : "01";
                if (normal_datetype == "DAY") d = curr_date[2] ? curr_date[2] : "01";
                if (normal_datetype == "HOUR") h = curr_date[3] ? curr_date[3] : "00";
                if (normal_datetype == "MINUTE") m = curr_date[4] ? curr_date[4] : "00";
                if (normal_datetype == "SECOND") s = curr_date[5] ? curr_date[5] : "00";
                if (normal_datetype == "MILLISECOND") ms = curr_date[6] ? curr_date[6] : "000";
            }
        }

        // 예외케이스
        if (edit_formattype == "TIME")
        {
            y = curr_date[0] ? curr_date[0] : "0000";
            M = curr_date[1] ? curr_date[1] : "01";
            d = curr_date[2] ? curr_date[2] : "01";
        }

        // 최종 보정
        if (!nexacro._isNull(y))
        {
            // YY editformat에 따라 입력된 값에 기존(현재)값이 존재하는 경우 보정 반영
            if (y.length == 2 && curr_date[0] && curr_date[0].length == 4)
            {
                // delete or backspace로 지우기만 한 경우 0 채우기 (RP 98941)
                y = nexacro.replaceAll(y, " ", "0");
                y = curr_date[0].substr(0, 2) + y;
            }
            else
            {
                y = y.padLeft(4, "0");
            }
        }
        if (!nexacro._isNull(M)) { M = M.padLeft(2, "0"); if (M != "00") M -= 1; }
        if (!nexacro._isNull(d)) { d = d.padLeft(2, "0"); if (d == "00") d = "01"; }
        if (!nexacro._isNull(h)) { h = h.padLeft(2, "0") }
        if (!nexacro._isNull(m)) { m = m.padLeft(2, "0") }
        if (!nexacro._isNull(s)) { s = s.padLeft(2, "0") }
        if (!nexacro._isNull(ms)) { ms = ms.padLeft(3, "0") }

        if (M == -1) M = "00";
        if (d == "  ") d = "01";

        // Date 객체화
        date_obj = new nexacro.Date(y, M, d, h, m, s, ms);

        if (edit_formattype == "TIME")
        {
            date_obj._timeonly = true;
        }

        return date_obj.toString();
    };

    _pMaskTypeDate.convertToDateObject = function (v, type)
    {
        if (v instanceof nexacro.Date)
        {
            v = v.toString();
        }

        if (nexacro._isNull(v) || v === "" || v.trim() === "")
        {
            return v;
        }

        var y, M, d;
        var h, m, s, ss;
        //var str = "";

        var editformattype = this.getEditFormatType();
        if (!nexacro._isNull(type))
            editformattype = type;

        switch (editformattype)
        {
            case 0: //Date
                y = v.substr(0, 4);
                M = v.substr(4, 2) || "01";
                d = v.substr(6, 2) || "01";
                break;
            case 1: //Time
                y = "0000";
                M = "01";
                d = "01";
                h = v.substr(0, 2);
                m = v.substr(2, 2);
                s = v.substr(4, 2);
                ss = v.substr(6, 3);
                break;
            case 2: default: //DateTime
                y = v.substr(0, 4);
                M = v.substr(4, 2) || "01";
                d = v.substr(6, 2) || "01";
                h = v.substr(8, 2);
                m = v.substr(10, 2);
                s = v.substr(12, 2);
                ss = v.substr(14, 3);
                break;
        }

        if (!nexacro._isNull(y)) y = y.padLeft(4, "0");
        if (!nexacro._isNull(M))
        {
            M = M.padLeft(2, "0");
            M -= 1;
        }

        if (!nexacro._isNull(d)) d = d.padLeft(2, "0");
        if (!nexacro._isNull(h)) h = h.padLeft(2, "0");
        if (!nexacro._isNull(m)) m = m.padLeft(2, "0");
        if (!nexacro._isNull(s)) s = s.padLeft(2, "0");
        if (!nexacro._isNull(ss)) ss = ss.padLeft(3, "0");

        var date = new nexacro.Date(y, M, d, h, m, s, ss);

        if (type == 1) date._timeonly = true;

        return date;
    };

    _pMaskTypeDate.changeMaskToType = function (mask)
    {
        var type = -1;
        var i, j;
        var maskList = [];
        var map = this._dateformatMap;
        var bFindMask = false;

        for (i = 0; i < map.length; i++)
        {
            maskList = map[i];
            if (bFindMask) break;

            for (j = 0; j < maskList.length; j++)
            {
                if (maskList[j] == mask)
                {
                    type = +(nexacro._toString(i) + nexacro._toString(j));
                    bFindMask = true;
                    break;
                }
            }
        }

        return type;
    };

    _pMaskTypeDate.changeTypeToDate = function (type)
    {
        var ret = "";

        if (type >= 0 && type < 10) ret = "YEAR";
        else if (type >= 10 && type < 20) ret = "MONTH";
        else if (type >= 20 && type < 30) ret = "DAY";
        else if (type >= 30 && type < 40) ret = "HOUR";
        else if (type >= 40 && type < 50) ret = "MINUTE";
        else if (type >= 50 && type < 60) ret = "SECOND";
        else if (type >= 60 && type < 70) ret = "MILLISECOND";

        return ret;
    };

    _pMaskTypeDate._appliedMaskString = function (info, text)
    {
        var ret = "";

        var type = info.type;
        var typeStr = nexacro._toString(type).padLeft(2, "0");
        var mask = info.mask;
        var masklen = mask.length;
        var maskchar = this.maskchar;

        var date = this._date;
        var val = text ? text : date[typeStr[0]];
        var bValidate = (date.length && !val) ? true : false;
        var intVal = (+val | 0);
        var jsDate = new Date(date[0], +date[1] - 1, date[2]);

        (function (_y, _obj)
        {
            if (_y <= 99 && _y >= 0)
            {

                var base_date = new Date(0, 0, 1);
                var base_fullyear = base_date.getFullYear();
                var fullyear = _obj.getFullYear();
                var calc_year = fullyear - base_fullyear;

                _obj.setFullYear(calc_year);
            }

        })(date[0], jsDate);

        if (!val)
        {
            val = "";
            for (var i = 0; i < masklen; i++)
            {
                val += maskchar;
            }
        }

        switch (type)
        {
            case 0:
                ret = val.padLeft(4, "0");
                break;
            case 1:
                ret = val.substr(2, 2);
                break;
            case 10:
            case 20:
                ret = val.padLeft(2, "0");
                break;
            case 30:
            case 40:
            case 50:
                //ret = val.padLeft(2, "0");
                ret = bValidate ? "00" : val.padLeft(2, "0");
                break;
            case 11:
            case 21:
            case 41:
            case 51:
                ret = nexacro._toString(intVal);
                break;
            case 31:
                if (intVal < 10)
                {
                    ret = nexacro._toString(intVal);
                }
                else
                {
                    ret = val;
                }
                break;
            case 32:
                if (intVal > 12 && intVal < 24)
                {
                    intVal -= 12;
                    val = nexacro._toString(intVal);
                }
                ret = val.padLeft(2, "0");
                break;
            case 33:
                if (intVal > 12 && intVal < 24)
                {
                    intVal -= 12;
                    val = nexacro._toString(intVal);
                }
                ret = val;
                break;
            case 60:
                ret = bValidate ? "000" : val.padLeft(3, "0");
                break;
            case 12:
                ret = this._monthlistL[intVal - 1];
                break;
            case 13:
                ret = this._monthlistS[intVal - 1];
                break;
            case 70:
                ret = this._datelistS[jsDate.getDay()];
                break;
            case 71:
                ret = this._datelistL[jsDate.getDay()];
                break;
            default:
                break;
        }

        return ret;
    };

    _pMaskTypeDate._getRemoveMaskString = function (type, val)
    {
        var ret = "";
        val = val.trim();
        switch (type)
        {
            case 0:
                ret = val.padLeft(4, "0").replace(/ /gi, "0");
                break;
            case 1:
                if (val)
                {
                    if (val.length == 4)
                    {
                        ret = val;
                    }
                    else if (val.length == 2)
                    {
                        ret = this._date.length ? this._date[0].substr(0, 2) + val : "00" + val;
                    }
                    else
                    {
                        ret = val.padLeft(4, "0");
                    }
                }
                else
                {
                    ret = val.padLeft(4, "0");
                }
                break;
            case 10:
            case 11:
                ret = (val && val !== "0") ? val.padLeft(2, "0") : "01";
                break;
            case 12:
                ret = this._date.length ? this._date[1] : "01";
                break;
            case 20:
            case 21:
                ret = (val && val !== "0") ? val.padLeft(2, "0") : "01";
                break;
            case 30:
            case 31:
            case 32:
            case 33:
            case 40:
            case 41:
            case 50:
            case 51:
                ret = val.padLeft(2, "0");
                break;
            case 60:
                ret = val.padLeft(3, "0");
                break;
        }
        return ret;
    };

    _pMaskTypeDate._getLocale = function ()
    {
        if (this.locale)
        {
            return this.locale;
        }
        else
        {
            return nexacro._getLocale();
        }
    };

