    //==============================================================================
    // nexacro.TriggerManager
    //==============================================================================
    nexacro.TriggerManager = function (form)
    {
        nexacro.Object.call(this);

        /* internal variable */
        this._form = form;
        this._triggers = { "len": 0 };
        this._inittriggers = [];
    };

    var _pTriggerManager = nexacro.TriggerManager.prototype = nexacro._createPrototype(nexacro.Object, nexacro.TriggerManager);
    _pTriggerManager._type_name = "TriggerManager";

    _pTriggerManager.destroy = function ()
    {
        this._form = null;
        this._triggers = null;
        this._inittriggers = null;

        nexacro.Object.prototype.destroy.call(this);
    };

    //===============================================================
    // nexacro.TriggerManager : Logical Part
    //===============================================================
    _pTriggerManager._settriggerinfo = function (contents)
    {
        if (!contents)
            return;

        var len = contents.length;
        var triggerobj;

        for (var i = 0; i < len; i++)
        {
            triggerobj = contents[i].triggerobj;

            if (nexacro._isArray(this._triggers[triggerobj]))
            {
                this._triggers[triggerobj].push(contents[i]);
            }
            else
            {
                this._triggers[triggerobj] = [contents[i]];
            }
        }
        this._triggers.len = len;
        this._inittriggers = contents;
    };

    _pTriggerManager.inittriggerinfo = function ()
    {
        var triggers = this._inittriggers;
        if (!triggers || triggers.len <= 0)
            return;

        var parent = this._form;
        if (!parent)
            return;

        var triggertype;
        var triggerobj;
        var triggerview;

        for (var i = 0; i < triggers.length; i++)
        {
            let trigger = triggers[i];
            triggertype = trigger.triggertype;

            // 기존 table 동작 호환용
            if (nexacro._trigger_type_table[trigger.triggertype])
            {
                triggertype = nexacro._trigger_type_table[trigger.triggertype];
            }
            
            if (triggertype)
            {
                triggerview = this._getTriggerView(trigger.triggerview);
                if (triggerview) 
                {
                    if (triggertype == "onmodelloadsuccess" || triggertype == "onmodelloadfail")
                    {
                        triggerview._ismodeltrigger = true;
                    }
                    else
                    {
                        triggerobj = (triggertype == "onload") ? triggerview : this._getTriggerObj(triggerview, trigger.triggerobj);

                        if (triggerobj) 
                        {
                            let notifytrigger = triggerview.on_notifytrigger;
                            if (notifytrigger && triggerobj._findEventHandler(triggertype, notifytrigger, triggerview))
                            {
                                triggerobj._addEventHandler(triggertype, notifytrigger, triggerview);
                            }
                        }
                    }
                }
            }
        }
    };

    _pTriggerManager._getTriggerView = function (obj, child_view)
    {
        var form = this._form;
        if (!form)
            return;

        var triggerview = obj;
        var targetview = null;
        var ret = null;

        let view_name = triggerview.split(".");
        if (child_view)
        {
            targetview = child_view[view_name.splice(0, 1)];
        }
        else if (view_name.length > 0)
        {
            targetview = form[view_name.splice(0, 1)];
        }

        // multi name 매칭
        if (targetview && view_name.length > 0)
        {
            targetview = this._getTriggerView(view_name.join("."), targetview);
        }

        if (!targetview)
        {
            targetview = form;
            // script 코딩이 되지 않기 때문에 targetview는 반드시 View나 Form이다
        }

        if (targetview._is_view || targetview._is_form)
            ret = targetview;

        return ret;
    };

    _pTriggerManager._getTriggerObj = function (obj, triggerobj, child)
    {
        var form = this._form;
        if (!form)
            return;

        var triggerview = obj;
        var targetobj = null;

        if (!triggerview || !triggerobj)
            return;

        let obj_name = triggerobj.split(".");
        if (triggerview._is_view && !child)
        {
            // targetview: view(root)
            targetobj = triggerview._p_form[obj_name.splice(0, 1)];
        }
        else
        {
            // targetview: form(root), view(child), Div(child), Tabpage(child)
            targetobj = triggerview[obj_name.splice(0, 1)];
        }

        // multi name 매칭
        if (targetobj && obj_name.length > 0)
        {
            targetobj = this._getTriggerObj(targetobj, obj_name.join("."), true);
        }

        if (targetobj === undefined)
        {
            if (triggerview.name == triggerobj)
                targetobj = triggerview;
        }

        return targetobj;
    };

    // triggerview(form/view) 내 target의 name 가져오는 함수
    _pTriggerManager._getTargetName = function (targetobj, triggerview, triggertype)
    {
        if (!targetobj || !triggerview || triggertype == "onload")
            return "";

        if (targetobj._is_form)
            return targetobj == triggerview ? targetobj.name : "";

        let target_name = targetobj.name;
        if (triggerview._contains(targetobj))
        {
            while (targetobj.parent)
            {
                if (targetobj.parent == triggerview || targetobj.parent == triggerview._p_form)
                    break;

                targetobj = targetobj.parent;
                target_name = targetobj.name + "." + target_name;
            }
        }
        return target_name;
    };

    _pTriggerManager._findTrigger = function (triggertype, triggerobj, triggerview)
    {
        var triggers = this._triggers;
        var triggerview_name = this._getTargetName(triggerview, this._form, triggertype); // triggerview가 ""가 아닐때 처리용
        var triggerobj_name = this._getTargetName(triggerobj, triggerview, triggertype); // triggerobj 찾아오는 함수
        var targetobj = triggers[triggerobj_name];
        var targettrigger = [];

        if (!targetobj)
            return;
        // 같은 triggertype, triggerview, triggerobj가 있을 수 있으므로 list로 전달해야함.
        for (var i = 0; i < targetobj.length; i++)
        {
            if (targetobj[i].targetaction)
            {
                let target_triggertype = targetobj[i].triggertype;

                // 기존 table 동작 호환
                if (nexacro._trigger_type_table[targetobj[i].triggertype])
                {
                    target_triggertype = nexacro._trigger_type_table[targetobj[i].triggertype];
                }

                if (triggertype == target_triggertype &&
                    (targetobj[i].triggerview == "" || triggerview_name == targetobj[i].triggerview))
                {
                    targettrigger.push(targetobj[i]);
                }
            }
        }

        return targettrigger;
    };

    _pTriggerManager._getAction = function (straction)
    {
        var form = this._form;
        if (!straction || !form)
            return undefined;

        straction = straction.toString();
        var ret = form[straction];

        if (ret && ret instanceof nexacro.Action)
            return ret;

        return undefined;

    };

    _pTriggerManager._notifyTrigger = function (triggertype, triggerobj, triggerview, evt)
    {
        if (!triggertype || !triggerobj || !triggerview)
            return;

        // triggertype은 Form에서 바꿔서 전달.
        var targettrigger = this._findTrigger(triggertype, triggerobj.name, triggerview.name);
        if (!targettrigger || targettrigger.length <= 0)
            return;

        var len = targettrigger.length;
        var ret = true;

        for (var i = 0; i < len; i++)
        {
            if (targettrigger[i].condition)
            {
                var condition = targettrigger[i].condition;
                var exprfn = this._createExprFunc(condition, triggerview._viewdataset);

                ret = exprfn.call(this._form, triggerview, triggerobj, this._form);
            }

            if (ret)
            {
                var action = this._getAction(targettrigger[ i ].targetaction);
                if (action)
                {
                    action._setEventInfo(evt);
                    action.run();
                }
            }
            else
                ret = true;
        }
    };

    _pTriggerManager._createExprFunc = function (expr_str, ds)
    {
        return nexacro._createExprFunc(expr_str, ds, ["triggerview", "triggerobj", "form"]);
    };

    _pTriggerManager = null;

