    _pTabBarControl.set_extrabuttoncount = function (val)
    {
        if (val !== undefined)
        {
            if (isNaN(val = +val) || val < 0)
                return;

            if (val > 5)
                val = 5; // extrabutton 은 최대 5개까지만 지원
        }

        if (this._p_extrabuttoncount != val)
        {
            this._p_extrabuttoncount = val;
            this.on_apply_extrabuttoncount();
        }
    };

