    {
        const buttonset = this._buttonset;
        if (buttonset)
            buttonset.setExtraButtonInfo(this._p_extrabuttoncount, this._p_extrabuttontooltiptext);

        if (this._is_created_contents)
        {
            this._recalcLayout();
            this.updateScrollButtonState();
        }
    };

