    //==============================================================================
    // nexacro.Frame Style Part
    //==============================================================================
    //not supported

    _pFrame.on_apply_font = function (font)
    {
        nexacro.Component.prototype.on_apply_font.call(this, font);

        // Frame은 font 변경되면 하위 Frame의 rem, em position 갱신
        if (this._p_frames)
        {
            // frameset
            var frames = this._p_frames;
            var len = frames.length;
            for (var i = 0; i < len; i++)
            {
                if (frames[i])
                {
                    if (this._getWindow() != frames[i]._getWindow())
                        continue;

                    frames[i]._update_position();
                }
            }
        }
        else
        {
            // system font synchronize with mainframe or popupframe
            if (this._isMainFrame() || this._is_popup_frame)
            {
                var control_elem = this.getElement();
                if (control_elem && control_elem.handle)
                {
                    var _handle = control_elem.handle;
                    control_elem._refreshControl(_handle, _handle.style);
                }
            }
        }

        // self
        this._update_position();

        // rem 단위 속성 재계산: MainFrame font 변경 (하위 Frame, Form, Component 순 전파)
        this._reapplyRemValues();
    };

    _pFrame._reapplyRemValues = function ()
    {
        if (this._p_frames)
        {
            var frames = this._p_frames;
            for (var i = 0, len = frames.length; i < len; i++)
            {
                if (frames[i] && this._getWindow() == frames[i]._getWindow())
                    frames[i]._reapplyRemValues();
            }
        }
        else if (this._p_frame)
            this._p_frame._reapplyRemValues();
        else if (this._p_form)
            this._p_form._reapplyRemValues();
    };

